import { cn } from '@/lib/utils'
import { Fungsional } from '@/models/asesmen-keperawatan-rawat-inap'

type PengkajianFungsionalProps = {
  data: Fungsional
}

const PengkajianFungsional = ({ data }: PengkajianFungsionalProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>PENGKAJIAN FUNGSIONAL</p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            Kriteria Barthel Index
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>Hasil</p>
        </div>
      </div>
      <Item k='Makan?' v={data.f1} />
      <Item k='Aktivitas di toilet' v={data.f2} />
      <Item
        k='Berpindah dari kursi roda ke tempat tidur/sebaliknya, termasuk duduk di tempat tidur'
        v={data.f3}
      />
      <Item
        k='Kebersihan diri, mencuci muka, menyisir rambut, menggosok gigi'
        v={data.f4}
      />
      <Item k='Mandi' v={data.f5} />
      <Item k='Berjalan di permukaan datar' v={data.f6} />
      <Item k='Naik turun tangga' v={`${data.f7}`} />
      <Item k='Berpakaian' v={`${data.f8}`} />
      <Item k='Mengontrol defekasi' v={`${data.f9}`} />
      <Item k='Mengontrol Berkemih' v={`${data.f10}`} />
      <Item isLast k='Total Skor' v={`${data.nilai}`} />
    </div>
  )
}

export default PengkajianFungsional

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}
