import { cn } from '@/lib/utils'
import type { AlatUkur } from '@/models/asesmen-geriatri'

type SpmsqGeriatriProps = {
  data: AlatUkur
}

const SpmsqGeriatri = ({ data }: SpmsqGeriatriProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>
        Short Portable Mental Status Questionnaire (SPMSQ) Geriatri
      </p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            PERTANYAAN
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            JAWABAN
          </p>
        </div>
      </div>
      <Item
        k='Tanggal berapa hari ini?'
        v={data.n1 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Hari apa sekarang ini?'
        v={data.n2 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Apa nama tempat ini?'
        v={data.n3 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Dimana alamat anda?'
        v={data.n4 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Berapa umur anda?'
        v={data.n5 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Kapan anda lahir?'
        v={data.n6 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Siapa presiden Indonesia sekarang?'
        v={data.n7 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Siapa presiden sebelumnya?'
        v={data.n8 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Siapa nama kecil ibu anda?'
        v={data.n9 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item
        k='Kurang 3 dari 20  dan tetap pengurangan	3	dari	setiap	angka baru, semua secara menurun !'
        v={data.n10 == 0 ? 'Menjawab Benar' : 'Menjawab Salah'}
      />
      <Item isLast k='Total Skor' v={`${data.total}`} />
      <p className='whitespace-pre-wrap mt-2'>
        {`KESIMPULAN : \n1. Kesalahan 0 - 2 = Fungsi intelektual utuh \n2.Kesalahan 3 - 4 = Kerusakan intelektual Ringan \n3. Kesalahan 5 - 6 = Kerusakan intelektual Sedang \n4. Kesalahan 8 - 10 = Kerusakan intelektual Berat`}
      </p>
    </div>
  )
}

export default SpmsqGeriatri

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}
