import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { getPemeriksaanRadiologi } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { PemeriksaanRadiologi } from './pemeriksaan-radiologi'

interface HasilPemeriksaanRadiologiProps {
  isReport?: boolean
  noreg?: string
}

const HasilPemeriksaanRadiologi = ({
  noreg = '',
  isReport = false,
}: HasilPemeriksaanRadiologiProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.hasilRadiologi, noreg],
    queryFn: () =>
      getPemeriksaanRadiologi({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 14a'>
      <div className='p-4'>
        <HeaderFormulir
          nama={pasien!.nama_pasien}
          tanggalLahir={pasien!.tgl_lahir}
          noRm={pasien!.no_rm}
          nik={pasien!.nik}
        >
          <h3>HASIL PEMERIKSAAN RADIOLOGI</h3>
        </HeaderFormulir>

        <div className='mt-4'>
          <PemeriksaanRadiologi data={res} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default HasilPemeriksaanRadiologi
