import { SimpleColumn } from '@/components/simple-column'
import { ResikoJatuh } from '@/models/asesmen-keperawatan-igd-anak'

const ResikoJatuhTableIgdAnak = ({ data }: { data: ResikoJatuh }) => {
  return (
    <div className='border border-black my-1 p-2'>
      <p className='flex-1 font-semibold'>Pengkajian Resiko Jatuh</p>
      {/* Table Head */}
      <div className=' flex'>
        <SimpleColumn head name='NO' className='w-[50px]' />
        <SimpleColumn head name='PARAMETER' />
        <SimpleColumn head name='HASIL' isLast />
      </div>
      {/* Table Head */}
      {/* Table Body */}
      <Row no='1' parameter='Umur' name={data.umur} />
      <Row no='2' parameter='Jenis Kelamin' name={data.jenis_kelamin} />
      <Row no='3' parameter='Diagnosa' name={data.dignosa} />
      <Row no='4' parameter='Gangguan Kognitif' name={data.gangguan_kognitif} />
      <Row no='5' parameter='Faktor Lingkungan' name={data.faktor_lingkungan} />
      <Row no='6' parameter='Response' name={data.response} />
      <Row no='7' parameter='Penggunaan Obat' name={data.penggunaan_obat} />
      <Row no='' parameter='Total' name={`${data.total}`} />
      {/* Table Body */}
    </div>
  )
}

export default ResikoJatuhTableIgdAnak

const Row = ({
  no,
  parameter,
  name,
}: {
  no: string
  parameter: string
  name: string
}) => {
  return (
    <div className=' flex'>
      <SimpleColumn name={no} className='w-[50px]' />
      <SimpleColumn name={parameter} />
      <SimpleColumn name={name} isLast />
    </div>
  )
}
