import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import type { DmasukKeluarIcu } from '@/models/masuk-keluar-icu'
import { getMasukKeluarIcu } from '@/services/masuk-keluar-icu'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportKriteriaMasukKeluarIcuProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  kategori: 'MASUK' | 'KELUAR'
}

const kriteriaMasuk: { prioritas: number; kriteria: string; deskripsi: string }[] =
  [
    {
      prioritas: 1,
      kriteria:
        'Prioritas 1\n\nKelompok ini merupakan pasien sakit kritis, tidak stabil yang memerlukan terapi intensif dan tertitrasi, seperti : dukungan/ bantuan ventilasi dan alat bantu suportif organ/ sistim lain, infus obat-obat vasoaktif kontinyu, obat anti aritmia kontinyu, pengobatan kontinyu tertitrasi, dan lain-lainnya. Terapi pada pasien prioritas 1 (satu) umumnya tidak mempunyai batas.',
      deskripsi:
        '- Tanda – tanda vital tidak stabil (tekanan darah, nadi, napas)\n- Aritmia jantung dengan gangguan hemodinamik\n- Pasca RJPO\n- Kejang lama dan atau berulang',
    },
    {
      prioritas: 2,
      kriteria:
        'Prioritas 2\n\nPasien ini memerlukan pemantauan canggih di UPI, sebab sangat berisiko bila tidak mendapatkan terapi intensif segera, terapi pada pasien prioritas 2 (dua) tidak mempunyai batas, karena kondisi medisnya senantiasa berubah.',
      deskripsi:
        '- Monitor akses vena sentral\n- Bedah kritis\n- Multiple trauma\n- Perdarahan internal akut\n- Perdarahan intracranial\n- Gangguan kesadaran\n- Anemia gravis\n- Sindroma koroner akut',
    },
    {
      prioritas: 3,
      kriteria:
        'Prioritas 3\n\nPasien golongan ini adalah pasien sakit kritis, yang tidak stabil status kesehatan sebelumnya, penyakit yang mendasarinya, atau penyakit akutnya, secara sendirian atau kombinasi. Kemungkinan sembuh dan/ atau manfaat terapi di UPI pada golongan ini sangat kecil (tahap terminal). Pengelolaan pada pasien golongan ini hanya untuk mengatasi kegawatan akutnya saja, dan usaha terapi mungkin tidak sampai melakukan intubasi atau resusitasi jantung paru.',
      deskripsi:
        '- Kanker stadium IV dengan disertai berbagai penyulit.\n- Penyakit paru dengan kerusakan paru yang luas yaitu mengenai satu paru atau lebih.\n- Sirosis hepatis dengan disertai penyulit akibat gagal hati.\n- Gagal ginjal yang tidak mungkin dilakukan hemodialisa karena kondisi yang tidak memungkinkan.\n- Pasien dengan kerusakan otak yang luas oleh sebab apapun (GCS < 5).\n- Pasien bedah kritis yang tidak dapat dioperasi karena kondisi yang tidak memungkinkan.',
    },
    {
      prioritas: 4,
      kriteria:
        'Kriteria Pengecualian\n\nDengan pertimbangan luar biasa, dan atas persetujuan kepala UPI, indikasi masuk pada beberapa golongan pasien bisa dikecualikan, dengan catatan bahwa pasien golongan demikian sewaktu-waktu harus bisa dikeluarkan dari UPI agar fasilitas UPI yang terbatas tersebut dapat digunakan untuk pasien prioritas 1,2,3 (satu, dua, tiga).',
      deskripsi: '- Do not resuscitate\n- Vegetative permanen\n- Mati batang otak',
    },
  ]

const kriteriaKeluar: { prioritas: number; kriteria: string; deskripsi: string }[] =
  [
    {
      prioritas: 1,
      kriteria: 'Prioritas 1',
      deskripsi:
        '- Tidak memerlukan terapi intensif dan monitoring\n- Jalan nafas dan pernafasan stabil\n- Tanda-tanda vital stabil',
    },
    {
      prioritas: 2,
      kriteria: 'Prioritas 2',
      deskripsi:
        '- Terapi maksimal dan prognosis jelek. (contoh : pasien dengan tiga/ lebih gagal sistem organ yang tidak berespon terhadap pengelolaan agresif)\n- Keberhasilan terapi tidak maksimal\n- Rujuk ke rumah sakit lain untuk penanganan lebih lanjut',
    },
    {
      prioritas: 3,
      kriteria: 'Prioritas 3',
      deskripsi: '- Atas permintaan keluarga atau pasien',
    },
    {
      prioritas: 4,
      kriteria: 'Prioritas 4',
      deskripsi: '- Pasien meninggal',
    },
  ]

const ReportKriteriaMasukKeluarIcu = ({
  isReport,
  noreg,
  kdBagian,
  kategori,
}: ReportKriteriaMasukKeluarIcuProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.masukKeluarIcu,
      noreg,
      kategori,
    ],
    queryFn: () => getMasukKeluarIcu(noreg!, kdBagian!, kategori),
    enabled: !!noreg,
  })

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const res: DmasukKeluarIcu | null = data != null ? data.response : null

  if (res == null || res.noreg == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const listKriteria = kategori == 'MASUK' ? kriteriaMasuk : kriteriaKeluar

  const Signature = () => {
    return (
      <div className='flex items-end justify-between pt-10'>
        {/* Nama Keluarga */}
        <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
          <p className='font-medium'>Nama Keluarga</p>
          {res.keluarga_ttd != '' ? (
            <img
              alt='ttd'
              src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${res.keluarga_ttd}`}
              className='h-[100px] w-[100px] object-contain'
            />
          ) : (
            <div className='h-[50px]' />
          )}
          <p>( {res.nama_keluarga} )</p>
        </div>
        {/* DPJP */}
        <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
          <p className='font-medium'>Baturaja, {formatDate(res.insert_dttm)}</p>
          <p className='font-medium'>DPJP</p>
          {res.nama_dokter ? (
            <>
              <QRCode
                value={res.nama_dokter}
                className='h-[50px] w-[50px]'
              />
              <p>( {res.nama_dokter} )</p>
            </>
          ) : (
            <div className='h-[50px]' />
          )}
        </div>
      </div>
    )
  }

  return (
    <LayoutBorderNo
      isReport={isReport}
      no={kategori == 'MASUK' ? 'RM 11d.3' : 'RM 11d.4'}
      rev='01.2020'
    >
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3'>
            KRITERIA PASIEN {kategori.toUpperCase()} ICU
          </h3>
        </HeaderFormulir>

        <div className='border border-black p-1 mb-1'>
          <table className='w-full text-xs'>
            <tbody>
              {listKriteria.map((item) => (
                <tr
                  key={item.prioritas}
                  className='border border-black align-top'
                >
                  <td className='border border-black p-1 w-1/2 whitespace-pre-line'>
                    {res.prioritas == item.prioritas
                      ? `✔ ${item.kriteria}`
                      : item.kriteria}
                  </td>
                  <td className='border border-black p-1 w-1/2 whitespace-pre-line'>
                    {item.deskripsi}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <Signature />
      </div>
    </LayoutBorderNo>
  )
}

export default ReportKriteriaMasukKeluarIcu