import Text from '@/components/text'

const PemeriksaanFisikDefault = ({
  anggotaGerak,
  dada,
  genetalia,
  kepala,
  perut,
}: {
  kepala: string
  dada: string
  perut: string
  anggotaGerak: string
  genetalia: string
}) => {
  return (
    <div>
      <Text k='Kepala dan Leher' v={kepala ?? '-'} />
      <Text k='Dada' v={dada ?? '-'} />
      <Text k='Perut dan Pinggang' v={perut ?? '-'} />
      <Text k='Anggota Gerak' v={anggotaGerak ?? '-'} />
      <Text k='Genetalia Dan Anus' v={genetalia ?? '-'} />
    </div>
  )
}

export default PemeriksaanFisikDefault
