import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import DiagnosaWrapper from '@/features/laporan-operasi/components/diagnosa-wrapper'
import Item from '@/features/laporan-operasi/components/item'
import { getLaporanTindakan } from '@/services/laporan-operasi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

interface LaporanTindakanProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

const LaporanTindakanKebidanan = ({
  isReport,
  noreg = '',
  kdBagian,
}: LaporanTindakanProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.laporanTindakanKebidanan, noreg],
    queryFn: () =>
      getLaporanTindakan({
        no_reg: noreg!,
        kd_bagian: 'MARI',
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || kdBagian != 'MARI')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  function Tindakan() {
    if (res == null) return

    const bidan = res.user.find((i) => i.keterangan == 'Bidan')

    return (
      <LayoutBorderNo isReport={isReport} no='RM 17m' rev='03.2020'>
        <div className='p-4'>
          <HeaderFormulir
            nama={pasien!.nama_pasien}
            tanggalLahir={pasien!.tgl_lahir}
            noRm={pasien!.no_rm}
            nik={pasien!.nik}
          >
            <h3>LAPORAN TINDAKAN KEBIDANAN</h3>
          </HeaderFormulir>

          {/* Table */}
          {/* Header */}
          <div className='flex mt-4'>
            <SimpleColumn
              name='Tanggal Tindakan'
              className='text-xs flex-1 bg-green-200'
            />
            <SimpleColumn
              name='Jam Tindakan Dimulai'
              className='text-xs flex-1 bg-green-200'
            />
            <SimpleColumn
              name='Jam Tindakan Selesai'
              className='text-xs flex-1 bg-green-200'
              isLast
            />
          </div>
          {/* Header */}

          {/* Body */}
          <div className='flex'>
            <SimpleColumn
              name={formatDate(res.tindakan.tanggal)}
              className='text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={res.tindakan.mulai}
              className='text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={res.tindakan.selesai}
              className='text-xs flex-1 border-t-0'
              isLast
            />
          </div>
          {/* Body */}

          <DiagnosaWrapper title='A. DIAGNOSA PENYAKIT ( ICD 10 ) PRE TINDAKAN'>
            {res.diagnosa
              .filter((i) => i.jenis_diagnosa == 'pre')
              .map((item, idx) => (
                <Item
                  key={idx}
                  number={`${idx + 1}`}
                  name={`${item.code} ${item.diagnosa}`}
                />
              ))}
          </DiagnosaWrapper>

          <DiagnosaWrapper title='B. DIAGNOSA PENYAKIT ( ICD 10 ) POST TINDAKAN'>
            {res.diagnosa
              .filter(
                (i) => i.jenis_diagnosa == 'post' && i.keterangan == 'icd10',
              )
              .map((item, idx) => (
                <Item
                  key={idx}
                  number={`${idx + 1}`}
                  name={`${item.code} ${item.diagnosa}`}
                />
              ))}
          </DiagnosaWrapper>

          <DiagnosaWrapper title='C.PROCEDURE - TINDAKAN BEDAH ( ICD 9 )'>
            {res.procedure.map((item, idx) => (
              <Item
                key={idx}
                number={`${idx + 1}`}
                name={`${item.kode2} ${item.description}`}
              />
            ))}
            {res.diagnosa
              .filter(
                (i) => i.jenis_diagnosa == 'post' && i.keterangan == 'icd9',
              )
              .map((item, idx) => (
                <Item
                  key={idx}
                  number={`${idx + 1}`}
                  name={`${item.code} ${item.diagnosa}`}
                />
              ))}
          </DiagnosaWrapper>

          <div className='border p-2 border-t-0 border-black bg-green-200'>
            <div>
              <p className='text-xs'>URAIAN</p>
            </div>
          </div>

          <div className='border border-black p-2 border-t-0 min-h-[50px]'>
            <p className='text-xs whitespace-pre-wrap'>{res.tindakan.uraian}</p>
          </div>

          <div className='border border-black p-2 border-t-0'>
            <p className='text-xs whitespace-pre-wrap'>
              Klasifikasi : {res.tindakan.klasifikasi}
            </p>
          </div>

          <div className='border border-black p-2 border-t-0'>
            <p className='text-xs whitespace-pre-wrap'>
              P.A Dikirim : {res.tindakan.patologi}
            </p>
          </div>
        </div>

        {/* Dokter  */}
        {bidan && (
          <div className='flex justify-between p-4'>
            <div className='flex flex-col text-center justify-center items-center'>
              <p className='text-xs text-white'>-</p>
              <QRCode value={bidan.nama} className='h-[50px] w-[50px] my-4' />
              <p className='text-xs underline'>{bidan.nama}</p>
              <p className='text-xs'>Bidan</p>
            </div>

            {/*  */}

            <div className='flex flex-col text-center justify-center items-center'>
              <p className='text-xs'>
                Baturaja, {formatDateTime(res.tindakan.insert_dttm)}
              </p>
              <QRCode value={res.dpjp} className='h-[50px] w-[50px] my-4' />
              <p className='text-xs underline'>{res.dpjp}</p>
              <p className='text-xs'>Dokter</p>
            </div>
          </div>
        )}
        {/* Dokter  */}
      </LayoutBorderNo>
    )
  }

  return (
    <>
      <Tindakan />
    </>
  )
}

export default LaporanTindakanKebidanan
