import { ReactNode } from 'react'

import { ReportFooter } from './report-footer'
import { ReportHeader } from './report-header'

export function LayoutBorderNo({
  children,
  no,
  rev,
  isReport = false,
}: {
  children: ReactNode
  no?: string
  rev?: string
  isReport?: boolean
}) {
  return (
    <>
      <div className='border border-black mx-2 mb-2 section-to-print'>
        {/* Header */}
        {isReport && <ReportHeader no={no} />}
        {/* Header */}

        {/* Content */}
        {children}
        {/* Content */}
      </div>

      {/* Footer */}
      {isReport && <ReportFooter rev={rev} />}
      {/* Footer */}
    </>
  )
}
