import { cn } from '@/lib/utils'
import type { AlatUkur } from '@/models/asesmen-geriatri'

type SkalaDepresiGeriatriProps = {
  data: AlatUkur
}

const SkalaDepresiGeriatri = ({ data }: SkalaDepresiGeriatriProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>
        Short Portable Mental Status Questionnaire (SPMSQ) Geriatri
      </p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            PERTANYAAN
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>HASIL</p>
        </div>
      </div>
      <Item
        k='1.	Apakah anda sebenarnya puas dengan kehidupan anda'
        v={data.n1 == 0 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='2.	Apakah anda telah banyak menghentikan aktivitas dan minat – minat anda'
        v={data.n2 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='3.	Apakah anda merasa kehidupan anda kosong?'
        v={data.n3 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='4.	Apakah anda sering merasa hidup anda bosan ?'
        v={data.n4 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='5.	Apakah anda mempunyai semangat yang baik setiap saat ?'
        v={data.n5 == 0 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='6.	Apakah anda takut bahwa sesuatu yang buruk akan akan terjadi pada anda ?'
        v={data.n6 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='7.	Apakah anda merasa bahagia untuk sebagian besar hidup anda ?'
        v={data.n7 == 0 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='8.	Apakah anda sering merasa tidak berdaya ?'
        v={data.n8 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='9.	Apakah anda lebih senang tinggal di rumah dari pada pergi ke luar dan mengerjakan sesuatu hal yang baru '
        v={data.n9 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='Kurang 3 dari 20  dan tetap pengurangan	3	dari	setiap	angka baru, semua secara menurun !'
        v={data.n10 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='11.	Apakah anda pikir bahwa hidup anda sekarang ini menyenangkan '
        v={data.n11 == 0 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='12. Apakah anda merasa tidak berharga seperti perasaan anda saat ini ?'
        v={data.n12 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='13.	Apakah anda merasa penuh semangat  '
        v={data.n13 == 0 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='14.	Apakah anda merasa bahwa keadaan anda tidak ada harapan  '
        v={data.n14 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item
        k='15.	Apakah anda pikir bahwa hidup anda sekarang ini menyenangkan '
        v={data.n15 == 1 ? 'Ya' : 'Tidak'}
      />
      <Item isLast k='Total Skor' v={`${data.total}`} />
      <p className='whitespace-pre-wrap mt-2'>
        {`KETERANGAN : \n1. Skor 1 - 4 = Tidak Depresi \n2. Skor 5 - 9 = Risiko Depresi \n3. Skor >= 9 = Depresi`}
      </p>
    </div>
  )
}

export default SkalaDepresiGeriatri

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}
