// Judul skala terpilih utk 1 entri (cocokkan fragmen teks tersimpan)
const pilihSkalaAnak = (
  data: ReAsesmenResikoJatuhAnak,
  f: FaktorAnak,
): string => {
  const d = data ?? ({} as ReAsesmenResikoJatuhAnak)
  const map: Record<string, string> = {
    Umur: d.usia,
    'Jenis Kelamin': d.jenis_kelamin,
    Diagnosa: d.diagnosis,
    'Gangguan Kognitif': d.gangguan_kognitif,
    'Faktor Lingkungan': d.faktor_lingkungan,
    'Respon terhadap pembedahan, sedasi dan anestesi': d.respon,
    'Penggunaan Obat-obatan': d.penggunaan_obat,
  }
  const val = map[f.faktor] ?? ''
  const hit = f.risiko.find((r) => r.keys.some((k) => val.includes(k)))
  return hit ? hit.title : ''
}

const ReportPengkajianUlangResikoJatuhAnak = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangResikoJatuhAnakProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reAsesmenResikoJatuhAnak, noreg],
    queryFn: () =>
      getAllReAsesmenResikoJatuhAnak({ noReg: noreg!, kdBagian: kdBagian! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const faktor = buildFaktor()

  // Grup entri per tanggal -> header tanggal (colSpan) + baris jam
  const grouped = res.reduce<Record<string, ReAsesmenResikoJatuhAnak[]>>(
    (acc, d) => {
      const tgl = (d.insertDttm ?? '').substring(0, 10)
      acc[tgl] = acc[tgl] ?? []
      acc[tgl].push(d)
      return acc
    },
    {},
  )
  const tanggalList = Object.keys(grouped).sort()

  return (
    <div className='landscape:max-w-full landscape:m-0'>
      <style>{`
        @media print {
          @page {
            size: A4 landscape;
            margin: 10mm;
          }
          body {
            margin: 0;
            padding: 0;
          }
        }
      `}</style>
      <LayoutBorderNo isReport={isReport} no='RM RI 8d.2' rev='00.2026'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-2'>
              PENGKAJIAN ULANG PASIEN RISIKO JATUH ANAK
            </h3>
          </HeaderFormulir>

          <p className='text-justify text-black my-2'>
            Lakukan pengkajian (skoring) risiko jatuh pada saat terjadi
            perubahan kondisi pasien/therapi, saat pasien pindah ruangan lain,
            pasien risiko tinggi dikaji setiap 24 jam atau sesaat terjadi kasus
            jatuh.
          </p>

          <p className='text-black font-bold my-2 whitespace-pre-wrap'>
            {`SKOR : 7 - 11 Risiko Rendah (RR)\n       >= 12 Risiko Tinggi (RT)`}
          </p>

          <table className='w-full text-xs border-collapse'>
            <thead>
              <tr className='font-bold text-center'>
                <th
                  rowSpan={2}
                  className='border border-black p-2 w-[40px] align-middle'
                >
                  No.
                </th>
                <th
                  rowSpan={2}
                  className='border border-black p-2 w-[160px] align-middle'
                >
                  FAKTOR RISIKO
                </th>
                <th
                  rowSpan={2}
                  className='border border-black p-2 align-middle'
                >
                  SKALA
                </th>
                <th
                  rowSpan={2}
                  className='border border-black p-2 w-[50px] align-middle'
                >
                  SKOR
                </th>
                {tanggalList.map((tgl) => (
                  <th
                    key={tgl}
                    colSpan={grouped[tgl].length}
                    className='border border-black p-2'
                  >
                    {formatDate(tgl)}
                  </th>
                ))}
              </tr>
              <tr className='font-bold text-center'>
                {res.map((d, i) => (
                  <th
                    key={i}
                    className='border border-black p-2 w-[55px] whitespace-nowrap'
                  >
                    {formatDateTimev2(d.insertDttm)} WIB
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {faktor.map((f, fi) => (
                <Fragment key={fi}>
                  {f.risiko.map((r, ri) => (
                    <tr key={ri}>
                      {ri === 0 && (
                        <>
                          <td
                            rowSpan={f.risiko.length}
                            className='border border-black p-2 text-center align-middle'
                          >
                            {fi + 1}
                          </td>
                          <td
                            rowSpan={f.risiko.length}
                            className='border border-black p-2 align-middle font-semibold'
                          >
                            {f.faktor}
                          </td>
                        </>
                      )}
                      <td className='border border-black p-2'>{r.title}</td>
                      <td className='border border-black p-2 text-center'>
                        {r.skor}
                      </td>
                      {res.map((d, di) => (
                        <td
                          key={di}
                          className={cn(
                            'border border-black p-2 text-center font-bold',
                            pilihSkalaAnak(d, f) === r.title && 'bg-green-200',
                          )}
                        >
                          {pilihSkalaAnak(d, f) === r.title ? '✓' : ''}
                        </td>
                      ))}
                    </tr>
                  ))}
                </Fragment>
              ))}
            </tbody>
            <tfoot>
              <tr className='font-bold'>
                <td colSpan={3} className='border border-black p-2 text-right'>
                  Total Skor
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.total}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td colSpan={3} className='border border-black p-2 text-right'>
                  Nama Perawat
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td
                    key={di}
                    className='border border-black p-2 text-center text-[10px] break-words'
                  >
                    {d.nama_perawat || ''}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td colSpan={3} className='border border-black p-2 text-right'>
                  Paraf
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.nama_perawat ? (
                      <QRCode
                        value={d.nama_perawat}
                        className='w-[45px] h-[45px] mx-auto'
                      />
                    ) : null}
                  </td>
                ))}
              </tr>
            </tfoot>
          </table>

          <p className='text-black mt-3 whitespace-pre-wrap'>
            {`Daftar obat berisiko :
Alkohol              Psikotropika              Benzodiazepine
Anti Kejang    Antihistamin              Hypoglicemic Agent
Diuretik           Sedative / Narkotika   Antihipertensi`}
          </p>
        </div>
      </LayoutBorderNo>
    </div>
  )
}

export default ReportPengkajianUlangResikoJatuhAnak
