import type { PengkajianUlangNyeri } from '@/models/pengkajian-ulang-nyeri'
import type { Response } from '@/type'

import { patch } from './api-2'

const getPengkajianUlangNyeri = async (
  noreg: string,
): Promise<Response<PengkajianUlangNyeri[]>> => {
  const response = await patch(`/v4/asesmen-ulang-nyeri`, {
    noreg,
  })

  return response.data
}

export { getPengkajianUlangNyeri }
