import { ReportTransferInternal } from '@/models/transfer-internal'
import type { Response } from '@/type'

import { post } from './api-2'

const getAllTransferInternal = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<ReportTransferInternal[]>> => {
  const response = await post(`/v1/transfer-internal-report`, { no_reg: noreg })

  return response.data
}

export { getAllTransferInternal }
