import { post, put } from './api-2'

const getAsesmenAwalKeperawatanDewasaRanap = async ({
  noreg,
  kdBagian,
  kategori,
}: {
  noreg: string
  kdBagian: string
  kategori: string
}): Promise<Response<AsesmenKeperawatanRawatInap>> => {
  const response = await put(`/v4/pengkajian-awal-keperawatan-dewasa-ranap`, {
    no_reg: noreg,
    kd_bagian: kdBagian,
    pelayanan: 'RANAP',
    kategori: kategori,
  })

  return response.data
}

