export default function EmptyPlaceholder({
  message = '',
  children,
}: {
  message: string
  children?: React.ReactNode
}) {
  return (
    <div className='h-[calc(100vh-10rem)] flex flex-col flex-1 justify-center items-center'>
      <h3 className='text-gray-500 text-sm'>{message}</h3>
      <br />
      {children}
    </div>
  )
}
