import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { LembarSebabKematianResponse } from '@/models/lembar-sebab-kematian'
import { getLembarSebabKematian } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { formatDate } from '@/utils/formatDate'

interface LembarSebabKematianProps {
  isReport?: boolean
  noreg?: string
}

const INITIAL_DATA: LembarSebabKematianResponse = {
  insert_dttm: '',
  insert_user_id: '',
  no_reg: '',
  ia: '',
  ib: '',
  ic: '',
  ii: '',
  ii_terdapat_penyakit: '',
  i_lamanya_sakit: '',
  macam_rudapaksa: '',
  cara_kejadian_rudapaksa: '',
  sifat_jejas_rudapaksa: '',
  is_janin_lahir_mati: '',
  sebab_lahir_mati: '',
  is_peristiwa_persalinan: '',
  is_peristiwa_kehamilan: '',
  is_dilakukan_operasi: '',
  jenis_operasi: '',
  dokter: '',
}

const LembarSebabKematian = ({
  isReport = false,
  noreg = '',
}: LembarSebabKematianProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: ['lembar-sebab-kematian', noreg],
    queryFn: () => getLembarSebabKematian(noreg),
    enabled: !!noreg,
  })

  const result = data?.response != null ? data?.response : INITIAL_DATA

  console.log('result ', result)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result?.dokter == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 1a' rev='02.2020'>
      <HeaderFormulir
        nama={pasien?.nama_pasien ?? ''}
        tanggalLahir={pasien?.tgl_lahir ?? ''}
        noRm={pasien?.no_rm ?? ''}
        nik={pasien?.nik ?? ''}
      >
        <h3>LEMBAR SEBAB KEMATIAN</h3>
      </HeaderFormulir>

      <div className='border border-black flex p-2'>
        <div className='flex-1 border border-black px-2'>
          <p className='text-xs'>I.</p>
          <p className='text-xs'>
            a. Penyakit atau keadaan yang langsung menyebabkan kematian.
          </p>
          <p className='text-xs mt-[100px]'>
            b.c Penyakit-penyakit (bila ada) yang menjadi lantaran timbulnya
            sebab kematian tsb. Pada a, dengan menyebutkan penyakit yang menjadi
            pokok pangkal terakhir.
          </p>
        </div>
        <div className='flex-1 border border-black border-x-0 p-2'>
          <p className='text-xs my-4 font-semibold'>
            <span className='font-semibold'>{result.ia}</span>
            <br />
            a. Penyakit tsb. Dalam ruang a, disebabkan oleh (akibat dari) :
          </p>
          <p className='text-xs mb-[25px'>
            <span className='font-semibold'>{result.ib}</span>
            <br />
            b. Penyakit tsb. Dalam ruang b, disebabkan oleh (akibat dari) :
          </p>
          <p className='text-xs mt-[25px] font-semibold'>c. {result.ic}</p>
          <p className='text-xs mt-[25px]'>
            Disamping penyakit tersebut diatas, terdapat pula penyakit <br />{' '}
            <span className='font-semibold'>{result.ii_terdapat_penyakit}</span>
          </p>
        </div>
        <div className='flex-1 border border-black p-2'>
          <p className='text-xs'>
            Lamanya (kira-kira) mulai sakit hingga meninggal dunia :
            <span className='font-semibold'>{result.i_lamanya_sakit}</span>
          </p>
        </div>
      </div>

      <p className='text-xs font-medium p-2'>Keterangan Khusus untuk :</p>

      <div className='p-2'>
        <p className='text-xs'>I. MATI KARENA RUDAPAKSA (violet death)</p>
        <div className='ml-2'>
          <Text k='a. Macam rudapaksa.' v={result.macam_rudapaksa} />
          <Text
            k='b. Cara kejadian rudapaksa .'
            v={result.cara_kejadian_rudapaksa}
          />
          <Text
            k='c. Sifat jejas (kekerasan tubuh).'
            v={result.sifat_jejas_rudapaksa}
          />
        </div>
      </div>

      <div className='p-2'>
        <p className='text-xs'>II. KELAHIRAN MATI (Stillbirth)</p>
        <div className='ml-2'>
          <Text
            k='a. Apakah ini janin lahir mati.'
            v={result.is_janin_lahir_mati}
          />
          <Text k='b. Sebab kelahiran mati' v={result.sebab_lahir_mati} />
        </div>
      </div>

      <div className='p-2'>
        <p className='text-xs'>III. PERSALINAN –KEHAMILAN</p>
        <div className='ml-2'>
          <Text
            k='a. Apakah ini peristiwa persalinan.'
            v={result.is_peristiwa_persalinan}
          />
          <Text
            k='b. Apakah ini peristiwa kehamilan'
            v={result.is_peristiwa_kehamilan}
          />
        </div>
      </div>

      <div className='p-2'>
        <p className='text-xs'>IV. OPERASI</p>
        <div className='ml-2'>
          <Text
            k='a. Apakah ini dilakukan operasi'
            v={result.is_dilakukan_operasi}
          />
          <Text k='b. Jenis operasi' v={result.jenis_operasi} />
        </div>
      </div>

      <div className='h-[100px]' />

      <div className='w-full text-center items-center flex flex-col gap-4 mb-4'>
        {result.dokter != '' ? (
          <>
            <p className='text-xs font-medium'>
              Baturaja, {formatDate(result.insert_dttm)}
              <br />
              Yang memberi keterangan sebab kematian
            </p>
            {result.dokter != '' ? (
              <QRCode value={result.dokter} className='h-[50px] w-[50px]' />
            ) : (
              <div className='h-[100px]' />
            )}
            <p className='text-xs'>( {result.dokter} )</p>
          </>
        ) : (
          <div className='h-[100px]' />
        )}
      </div>
    </LayoutBorderNo>
  )
}

export default LembarSebabKematian

const Text = ({ k, v }: { k: string; v: string }) => {
  return (
    <div className='flex items-center'>
      <div className='w-[250px]'>
        <p className='text-xs'>{k}</p>
      </div>
      <p className='text-xs'>: {v}</p>
    </div>
  )
}
