import { Edit, Printer } from 'lucide-react'

import { Link } from '@tanstack/react-router'

import { Button } from '@/components/ui/button'
import { SkriningPasienLuar } from '@/models/skrining-pasien-luar'
import { useGlobalStore } from '@/store/global.store'
import { formatDate, formatDateTime } from '@/utils/formatDate'

function Row({ label, value }: { label: string; value?: string }) {
  return (
    <div className='flex gap-2 py-1 border-b border-gray-100 last:border-0'>
      <span className='min-w-[200px] text-sm text-gray-500'>{label}</span>
      <span className='text-sm font-medium text-gray-800 flex-1'>
        {value || '-'}
      </span>
    </div>
  )
}

function Section({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <div className='mb-5'>
      <h3 className='text-sm font-semibold text-blue-600 border-b border-blue-200 pb-1 mb-2'>
        {title}
      </h3>
      {children}
    </div>
  )
}

export function SkriningPasienLuarDetail({
  item,
}: {
  item: SkriningPasienLuar
}) {
  const { setDialogId, setShowDialog } = useGlobalStore()
  const d = item.data

  const handleEdit = () => {
    setDialogId('dialog-edit-skrining-pasien-luar')
    setShowDialog(true)
  }

  return (
    <div className='space-y-1'>
      <div className='flex items-center gap-4 justify-end mb-4'>
        <Button
          size='sm'
          variant='outline'
          onClick={handleEdit}
          className='gap-2'
        >
          <Edit className='h-4 w-4' />
          Edit
        </Button>
        {/* Print */}
        <Link to={`/skrining-pasien-luar/${item.id}`} target='_blank'>
          <Printer className='text-black hover:cursor-pointer' />
        </Link>{' '}
        {/* Print */}
      </div>

      <Section title='Data Pasien'>
        <Row label='Nama' value={d.nama} />
        <Row
          label='Tanggal Lahir'
          value={formatDate(formatDateTime(d.tanggal_lahir))}
        />
        <Row label='NIK' value={d.nik} />
        <Row label='Jenis Kelamin' value={d.jenis_kelamin} />
      </Section>

      <Section title='Data Pengirim'>
        <Row label='Tanggal & Jam' value={formatDateTime(item.insert_dttm)} />
        <Row label='Petugas' value={d.petugas} />
        <Row label='Identitas Pengirim' value={d.identitas_pengirim} />
        <Row label='No. HP' value={d.hp} />
        <Row label='Rujukan' value={d.rujukan} />
        <Row label='Cara Informasi Datang' value={d.cara_informasi_datang} />
      </Section>

      <Section title='Keluhan & Diagnosa'>
        <Row label='Diagnosa' value={d.diagnosa} />
        <Row label='Keluhan' value={d.keluhan} />
      </Section>

      <Section title='Vital Sign & GCS'>
        <Row label='GCS E' value={d.gcs_e} />
        <Row label='GCS M' value={d.gcs_m} />
        <Row label='GCS V' value={d.gcs_v} />
        <Row label='Tekanan Darah' value={d.td} />
        <Row label='Nadi' value={d.nadi} />
        <Row label='Suhu' value={d.suhu} />
        <Row label='Pernafasan' value={d.pernafasan} />
        <Row label='SpO2' value={d.spo2} />
      </Section>

      <Section title='Rencana & Saran'>
        <Row label='Kebutuhan Sarana' value={d.kebutuhan_sarana} />
        <Row label='Rekomendasi' value={d.rekomendasi} />
        <Row label='Saran' value={d.saran} />
      </Section>
    </div>
  )
}
