import { ReactNode } from 'react'
import QRCode from 'react-qr-code'

import { cn } from '@/lib/utils'

interface SimpleColumnProps {
  name?: string
  isLast?: boolean
  head?: boolean
  className?: string
  className2?: string
  hasQR?: boolean
  hasSignature?: boolean
  signatureUrl?: string
  isChild?: ReactNode
}

export function SimpleColumn({
  name,
  head,
  isLast,
  className = 'flex-1',
  className2 = '',
  hasQR = false,
  hasSignature = false,
  signatureUrl = '',
  isChild,
}: SimpleColumnProps) {
  if (isChild)
    return (
      <div
        className={cn(
          'flex flex-col gap-2  justify-center items-center p-[2px] border-y border-black border-l',
          isLast && 'border-r',
          className,
          head && 'bg-gray-100',
        )}
      >
        {isChild}
      </div>
    )

  return (
    <div
      className={cn(
        'flex flex-col gap-2  justify-center items-center p-1 border-y border-black border-l',
        isLast && 'border-r',
        className,
        head && 'bg-gray-100',
      )}
    >
      {hasQR && name != '' && (
        <QRCode value={name!} className='h-[50px] w-[50px]' />
      )}
      {hasSignature && signatureUrl != '' && (
        <img
          alt='ttd'
          src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${signatureUrl}`}
          className='h-[100px] w-[100px] object-contain'
        />
      )}
      {name != '' ? <p className={cn(className2)}>{name}</p> : null}
    </div>
  )
}
