import type {
  AsesmenPraAnestesi,
  AsesmenPraInduksi,
  AsesmenPraSedasi,
} from '@/models/asesmen-pra-varian'
import type { Response } from '@/type'

import { post } from './api-2'

const getAsesmenPraAnestesi = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<AsesmenPraAnestesi>> => {
  const response = await post(`/v1/asesmen-pra-anestesi`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

