import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { IntervensiSuicide } from '@/models/pengkajian-ulang-suicide'
import { getAllIntervensiSuicide } from '@/services/pengkajian-ulang-suicide'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportIntervensiSuicideProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

const intervensi = [
  'Identifikasi dan jauhkan peralatan atau barang-barang yang bisa dipakai oleh pasien untuk melakukan bunuh diri',
  'Berikan kesempatan kepada pasien untuk dikunjungi oleh anggota keluarga yang dapat memberikan dukungan psikis',
  'Libatkan pasien yang berisiko dan keluarga pasien tentang rencana perawatan pasien; rencana tersebut harus menyangkut perawatan setelah keluar dari rumah sakit',
  'Siagakan staf atau petugas untuk setiap tanda atau gejala akan terjadinya percobaan bunuh diri',
  'Memberikan kesempatan pasien mengungkapkan perasaannya tanpa menghakimi ',
  'Memberikan dukungan emosional rasa memberikan rasa aman dan motivasi ',
  'Mengajarkan koping positip, diktraksi positip dan aktivitas spritual',
  'Edukasi tanda dan bahaya resiko bunuh diri seperti sering bicara sendiri, prilaku menarik diri',
  'Mendokumentasi pengkajian, tindakan dan respon pasien',
  'Evaluasi berkala perkembangan dan penurunan resiko bunuh diri',
]

export function ReportIntervensiSuicide({
  isReport = false,
  noreg = '',
  kdBagian = '',
}: ReportIntervensiSuicideProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.intervensiSuicide,
      noreg,
      kdBagian,
    ],
    queryFn: () => getAllIntervensiSuicide(noreg, kdBagian),
  })

  const result = data?.response != null ? data?.response : []

  // group by date
  const groupedByDate: Record<string, IntervensiSuicide[]> = result.reduce(
    (acc, item) => {
      const date = formatDate(item.insert_dttm)
      if (!acc[date]) {
        acc[date] = []
      }
      acc[date].push(item)
      return acc
    },
    {} as Record<string, IntervensiSuicide[]>,
  )

  const dates = Object.keys(groupedByDate).sort()
  const shifts = ['Pagi', 'Siang', 'Malam']

  // Helper function to get checkmark for specific intervensi, date, and shift
  const getCheckmark = (
    dateStr: string,
    shiftName: string,
    resikoIndex: number,
  ): string => {
    const interventions = groupedByDate[dateStr] || []
    const shiftData = interventions.find((item) => item.shift === shiftName)
    if (!shiftData) return ''
    const key = `n${resikoIndex + 1}` as keyof IntervensiSuicide
    return shiftData[key] ? '✓' : ''
  }

  // Helper function to get nama perawat for specific date and shift
  const getNamaPerawat = (dateStr: string, shiftName: string): string => {
    const interventions = groupedByDate[dateStr] || []
    const shiftData = interventions.find((item) => item.shift === shiftName)
    if (!shiftData) return ''
    return shiftData.user || ''
  }

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <div className='landscape:max-w-full landscape:m-0'>
      <style>{`
        @media print {
          @page {
            size: A4 landscape;
            margin: 10mm;
          }
          body {
            margin: 0;
            padding: 0;
          }
        }
      `}</style>
      <LayoutBorderNo no='RM 23a' rev='01.2020' isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <HeaderFormulir
            nama={pasien!.nama_pasien}
            tanggalLahir={pasien!.tgl_lahir}
            noRm={pasien!.no_rm}
            nik={pasien!.nik}
          >
            <h3>
              FORMULIR INTERVENSI PENCEGAHAN <br />
              RISIKO BUNUH DIRI DAN MELUKAI DIRI SENDIRI
            </h3>
          </HeaderFormulir>

          <div className='mb-4'>
            {/* Header Row - Dates */}
            <div className='flex text-xs'>
              <SimpleColumn head name='No' className='w-[40px]' />
              <SimpleColumn
                head
                name='Intervensi Pencegahan Risiko Pasien Bunuh diri dan Melukai diri'
                className='flex-1'
              />
              {dates.map((date) => (
                <div key={date} className='flex'>
                  <SimpleColumn head name={date} className='w-[45px]' />
                  <SimpleColumn head name='' className='w-[45px]' />
                  <SimpleColumn
                    head
                    name=''
                    className='w-[45px]'
                    isLast={date === dates[dates.length - 1]}
                  />
                </div>
              ))}
            </div>

            {/* PKL Sub-header Row - Shifts */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn name='' className='flex-1 border-t-0 text-center' />
              {dates.map((date) => (
                <div key={`shifts-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`${date}-${shift}`}
                      name={shift}
                      className='w-[45px] border-t-0 text-center text-[10px]'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>

            {/* Intervention Rows */}
            {intervensi.map((intervensi, idx) => (
              <div key={idx} className='flex text-xs'>
                <SimpleColumn
                  name={`${idx + 1}.`}
                  className='w-[40px] border-t-0'
                />
                <SimpleColumn
                  name={intervensi}
                  className='flex-1 border-t-0 items-start'
                />
                {dates.map((date) => (
                  <div key={`${date}-${idx}`} className='flex'>
                    {shifts.map((shift) => (
                      <SimpleColumn
                        key={`${date}-${shift}-${idx}`}
                        name={getCheckmark(date, shift, idx)}
                        className='w-[45px] border-t-0 text-center font-bold'
                        isLast={
                          date === dates[dates.length - 1] &&
                          shift === shifts[shifts.length - 1]
                        }
                      />
                    ))}
                  </div>
                ))}
              </div>
            ))}

            {/* Nama Perawat Row */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn
                name='Nama perawat yang melakukan intervensi'
                className='flex-1 border-t-0 font-semibold'
              />
              {dates.map((date) => (
                <div key={`perawat-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`perawat-${date}-${shift}`}
                      name={getNamaPerawat(date, shift)}
                      className='w-[45px] border-t-0 text-center text-xs break-words overflow-hidden line-clamp-2'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
        {/* Content */}
      </LayoutBorderNo>
    </div>
  )
}
