import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { ReqLabModel } from '@/models/req-lab'
import { getAllReportReqLab } from '@/services/req-lab'
// import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportReqLabProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  noRm?: string
  id?: string
}

const ReportReqLab = ({
  isReport,
  noreg,
  kdBagian,
  noRm,
  id,
}: ReportReqLabProps) => {
  // const { pasien } = usePasienStore((state) => state)
  const [current, setCurrent] = useState<ReqLabModel | null>(null)
  const [selected, setSelected] = useState(-1)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemeriksaanLab, noreg],
    queryFn: () =>
      getAllReportReqLab({
        noreg: noreg!,
        kdBagian: kdBagian!,
        noRm: noRm!,
        id: id!,
      }),
    enabled: !!noreg,
  })

  const res =
    data != null ? data.response.filter((i) => i.tipe != 'RADIOLOGI') : []
  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <>
      <ul className='flex mb-4'>
        {res?.map((item, index) => (
          <li className='gap-4 mx-2 ml-2' key={index}>
            <Button
              variant={item.id == selected ? 'default' : 'outline'}
              onClick={() => {
                setSelected(item.id)
                setCurrent(res[index])
              }}
            >
              {index + 1}
            </Button>
          </li>
        ))}
      </ul>

      {current != null && (
        <LayoutBorderNo
          isReport={isReport}
          no={renderNo(current.tipe)}
          rev='01.2020'
        >
          <div className='p-4 text-xs'>
            <HeaderFormulir
              nama={current.pasien.nama_pasien}
              tanggalLahir={formatDate(current.pasien.tgl_lahir)}
              noRm={current.pasien.no_rm}
              nik={current.pasien.nik}
            >
              <h3 className='text-xs font-bold text-center py-3 whitespace-pre-wrap'>
                {renderTitle(current.tipe)}
              </h3>
            </HeaderFormulir>

            <div className='flex gap-4 items-center justify-between my-4'>
              <div>
                {!current.tipe.includes('RADIOLOGI') ? (
                  <TextField title='No.Lab' value={current.data.nomor_lab} />
                ) : (
                  <TextField title='No RO' value={current.data.nomor_lab} />
                )}
                <TextField
                  title='Tanggal Order'
                  value={current.data.tanggal_order}
                />

                <TextField
                  title='Tanggungan'
                  value={
                    current.data.tanggungan == ''
                      ? current.tanggungan
                      : current.data.tanggungan
                  }
                />

                <TextField
                  title='Jenis Kelamin'
                  value={current.pasien.jenis_kelamin}
                />
              </div>
              <div>
                <TextField title='DPJP' value={current.nama_dpjp} />
                {!current.tipe.includes('RADIOLOGI') && (
                  <TextField title='Diagnosis' value={current.data.diagnosis} />
                )}
                <TextField
                  title='Indikasi Klinis'
                  value={current.data.indikasi_klinis}
                />
                <TextField title='Ruangan' value={current.ruangan} />
                {current.tipe.includes('INTERNAL') && (
                  <TextField
                    title='Urgensi Pemeriksaan'
                    value={current.data.urgensi}
                  />
                )}
              </div>
            </div>

            {render(current.tipe, current)}
            {!current.tipe.includes('EKG') ||
              (!current.tipe.includes('RADIOLOGI') && (
                <Text
                  title='* Pemeriksaan dirujuk ke laboratorium lain'
                  value=''
                />
              ))}

            {renderTtd(current.tipe, current)}
          </div>
        </LayoutBorderNo>
      )}
    </>
  )

  function renderNo(type: string) {
    switch (type) {
      case 'RADIOLOGI':
        return 'RM 14d'
      case 'FISIOTERAPI':
        return 'RM 14i1'
      default:
        return 'RM 14c'
    }
  }

  function render(type: string, res: ReqLabModel) {
    switch (type) {
      case 'PATOLOGI_KLINIK_INTERNAL':
        return <PatologiKlinikInternal res={res} />
      case 'EKG':
        return <PermintaanPemeriksaan res={res} />
      case 'PATOLOGI_KLINIK_EKSTERNAL':
        return <PermintaanPemeriksaan res={res} />
      case 'RADIOLOGI':
        return <Radiologi res={res} />
      default:
        return null
    }
  }

  function renderTtd(tipe: string, res: ReqLabModel) {
    if (tipe == 'RADIOLOGI') {
      return (
        <div className='gap-4 p-1 mb-1'>
          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />

            <div className='w-full text-center flex justify-between items-center gap-2'>
              <div className='flex flex-col items-center gap-2'>
                <p className='font-medium'>
                  Baturaja, {formatDate(res.insert_dttm)}
                </p>
                <p className='font-medium'>Dokter Pengirim</p>
                {res.nama_pengirim ? (
                  <>
                    <QRCode
                      value={res.nama_pengirim}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res.nama_pengirim} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )}
              </div>
              <div className='flex flex-col items-center gap-2'>
                <p className='font-medium'>Menyetujui</p>
                <p className='font-medium'>Pasien / Keluarga</p>
                {res.keluarga_pasien ? (
                  <>
                    <QRCode
                      value={res.keluarga_pasien}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res.keluarga_pasien} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )}
              </div>
            </div>
          </div>
          {/* Tanda Tangan */}
        </div>
      )
    }

    return (
      <div className='gap-4 p-1 mb-1'>
        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />

          <div className='w-full text-center flex flex-col justify-between items-end gap-2'>
            <div className='flex flex-col items-center gap-2'>
              <p className='font-medium'>
                Baturaja, {formatDate(res.insert_dttm)}
              </p>
              <p className='font-medium'>Dokter Pengirim</p>
              {res.nama_pengirim ? (
                <>
                  <QRCode
                    value={res.nama_pengirim}
                    className='h-[50px] w-[50px]'
                  />
                  <p>( {res.nama_pengirim} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    )
  }
}

export default ReportReqLab

function Text({ title, value }: { title: string; value: string }) {
  return (
    <div className='mb-2'>
      <h3 className='font-bold'>{title}</h3>
      <p className='whitespace-pre-wrap'>{value.split(', ').join('\n')}</p>
    </div>
  )
}

function PatologiKlinikInternal({ res }: { res: ReqLabModel }) {
  return (
    <>
      <div className='flex justify-between border border-black'>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start  border-black'>
          {res.data.hematologi != '' && (
            <Text title='HEMATOLOGI' value={res.data.hematologi} />
          )}
          {res.data.hemostasis != '' && (
            <Text title='HEMOSTASIS' value={res.data.hemostasis} />
          )}
          {res.data.mikrobiologi != '' && (
            <Text title='MIKROBIOLOGI' value={res.data.mikrobiologi} />
          )}
        </div>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start border-l border-black'>
          {res.data.diabetes != '' && (
            <Text title='DIABETES' value={res.data.diabetes} />
          )}
          {res.data.fungsi_ginjal != '' && (
            <Text title='FUNGSI GINJAL' value={res.data.fungsi_ginjal} />
          )}
          {res.data.fungsi_hati != '' && (
            <Text title='FUNGSI HATI' value={res.data.fungsi_hati} />
          )}
          {res.data.lemak_darah != '' && (
            <Text title='LEMAK DARAH' value={res.data.lemak_darah} />
          )}
        </div>
        <div className=' min-h-[100px] flex flex-col flex-1 p-2 items-start border-l border-black'>
          {res.data.hepatitis != '' && (
            <Text title='HEPATITIS' value={res.data.hepatitis} />
          )}
          {res.data.hormon != '' && (
            <Text title='HORMON' value={res.data.hormon} />
          )}
          {res.data.elektrolit != '' && (
            <Text title='ELEKTROLIT' value={res.data.elektrolit} />
          )}
          {res.data.serologi != '' && (
            <Text title='SEROLOGI' value={res.data.serologi} />
          )}
          {res.data.urinalisa != '' && (
            <Text title='URINALISA' value={res.data.urinalisa} />
          )}
          {res.data.lain_lain != '' && (
            <Text title='LAIN LAIN' value={res.data.lain_lain} />
          )}
        </div>
      </div>
      <div className='flex border border-t-0 border-black mb-2'>
        <div className='p-2 flex-1 border-l border-black'>
          <Text title='Petugas Sampling :' value={res.data.petugas_sampling} />
        </div>
        <div className='p-2 flex-1 border-l border-black'>
          <Text title='Kualitas Sampel :' value={res.data.kualitas_sampel} />
        </div>
        <div className='p-2 flex-1 border-l border-black'>
          <Text title='Jam Sampling :' value={res.data.jam_sampling + ' WIB'} />
        </div>
        <div className='p-2 flex-1 border-l border-black'>
          <Text
            title='Jam Keluar Hasil :'
            value={res.data.jam_hasil + ' WIB'}
          />
        </div>
      </div>
    </>
  )
}

function PermintaanPemeriksaan({ res }: { res: ReqLabModel }) {
  return (
    <div className='flex items-start justify-between border border-black p-2 mb-4'>
      <Text
        title='Permintaan Pemeriksaan'
        value={res.data.permintaan_pemeriksaan}
      />
    </div>
  )
}

function Radiologi({ res }: { res: ReqLabModel }) {
  return (
    <>
      <div className='flex justify-between border border-black'>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start  border-black'>
          {res.data.ex_superior_dex != '' && (
            <Text
              title='EXTREMITAS SUPERIOR DEX'
              value={res.data.ex_superior_dex}
            />
          )}
        </div>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start  border-black'>
          {res.data.ex_superior_sin != '' && (
            <Text
              title='EXTREMITAS SUPERIOR SIN'
              value={res.data.ex_superior_sin}
            />
          )}
        </div>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start border-l border-black'>
          {res.data.ex_inferior_dex != '' && (
            <Text
              title='EXTREMITAS INFERIOR DEX'
              value={res.data.ex_inferior_dex}
            />
          )}
        </div>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start  border-black'>
          {res.data.ex_inferior_sin != '' && (
            <Text
              title='EXTREMITAS INFERIOR SIN'
              value={res.data.ex_inferior_sin}
            />
          )}
        </div>
      </div>
      <div className='flex justify-between border border-t-0 border-black'>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start  border-black'>
          {res.data.permintaan_pemeriksaan != '' && (
            <Text
              title='PERMINTAAN PEMERIKSAAN'
              value={res.data.permintaan_pemeriksaan}
            />
          )}
        </div>
        <div className='min-h-[100px] flex flex-col flex-1 p-2 items-start border-l border-black'>
          {res.data.pemeriksaan_ct_scan_non_kontras != '' && (
            <Text
              title='PERMINTAAN DENGAN CT SCAN NON KONTRAS'
              value={res.data.pemeriksaan_ct_scan_non_kontras}
            />
          )}
          {res.data.pemeriksaan_dengan_kontras != '' && (
            <Text
              title='PEMERIKSAAN DENGAN KONTRAS'
              value={res.data.pemeriksaan_dengan_kontras}
            />
          )}
          {res.data.usg != '' && <Text title='USG' value={res.data.usg} />}
        </div>
      </div>
    </>
  )
}

function renderTitle(title: string) {
  switch (title) {
    case 'PATOLOGI_ANATOMI':
      return 'PERMINTAAN\n PEMERIKSAAN LABORATORIUM \nPATOLOGI ANATOMI'
    case 'PATOLOGI_KLINIK_INTERNAL':
      return 'PERMINTAAN\n PEMERIKSAAN LABORATORIUM PATOLOGI \nKLINIK'
    case 'PATOLOGI_KLINIK_EKSTERNAL':
      return 'PERMINTAAN\n PEMERIKSAAN LABORATORIUM \nPATOLOGI KLINIK EKSTERNAL'
    case 'EKG':
      return 'PERMINTAAN\n PEMERIKSAAN EKG DAN SPIROMETRI'
    case 'RADIOLOGI':
      return 'PERMINTAAN\n PEMERIKSAAN RADIOLOGI'
    default:
      return ''
  }
}
