import { ReportAsesmenNeonatus } from '@/models/asesmen-neonatus'
import { Response } from '@/type'

import { post } from './api-2'

const getAsesmenNeonatus = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<ReportAsesmenNeonatus>> => {
  const response = await post(`/v1/perina-report-asesmen`, {
    no_reg: no_reg,
    kd_bagian: kd_bagian,
  })

  return response.data
}

export { getAsesmenNeonatus }
