import type { AsesmenTerminal } from '@/models/asesmen-terminal'
import type { Response } from '@/type'

import { post } from './api-2'

const getAsesmenTerminal = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<AsesmenTerminal[]>> => {
  const response = await post(`/v1/asesmen-terminal/all`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getAsesmenTerminal }
