import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { ReAsesmenResikoJatuhGeriatri } from '@/models/resiko-jatuh'
import { getAllReAsesmenResikoJatuhGeriatri } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTimev2 } from '@/utils/formatDate'

interface ReportPengkajianUlangResikoJatuhGeriatriProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

const KRITERIA: { key: keyof ReAsesmenResikoJatuhGeriatri; label: string }[] = [
  { key: 'n1', label: 'Gangguan gaya berjalan (diseret, menghentak, berayun)' },
  { key: 'n2', label: 'Pusing, pingsan pada posisi tegak' },
  { key: 'n3', label: 'Kebingungan setiap saat, misalnya demensia' },
  { key: 'n4', label: 'Nokturia / Inkontinesia' },
  {
    key: 'n5',
    label:
      'Kebingungan intermiten, misalnya delirium / Acute Confusional State',
  },
  { key: 'n6', label: 'Kelemahan Umum' },
  { key: 'n7', label: 'Obat-obatan berisiko tinggi' },
  { key: 'n8', label: 'Riwayat jatuh dalam 12 bulan terakhir' },
  { key: 'n9', label: 'Osteoporosis' },
  { key: 'n10', label: 'Gangguan pendengaran dan/atau penglihatan' },
  { key: 'n11', label: 'Usia 70 tahun ke atas' },
]

const ReportPengkajianUlangResikoJatuhGeriatri = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangResikoJatuhGeriatriProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.reAsesmenResikoJatuhGeriatri,
      noreg,
    ],
    queryFn: () =>
      getAllReAsesmenResikoJatuhGeriatri({
        noReg: noreg!,
        kdBagian: kdBagian!,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  // Grup entri per tanggal -> header tanggal (colSpan) + baris jam
  const grouped = res.reduce<Record<string, ReAsesmenResikoJatuhGeriatri[]>>(
    (acc, d) => {
      const tgl = (d.insert_dttm ?? '').substring(0, 10)
      acc[tgl] = acc[tgl] ?? []
      acc[tgl].push(d)
      return acc
    },
    {},
  )
  const tanggalList = Object.keys(grouped).sort()

  return (
    <div className='landscape:max-w-full landscape:m-0'>
      <style>{`
        @media print {
          @page {
            size: A4 landscape;
            margin: 10mm;
          }
          body {
            margin: 0;
            padding: 0;
          }
        }
      `}</style>
      <LayoutBorderNo isReport={isReport} no='RM RI 8d.3' rev='01.2020'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-2'>
              PENGKAJIAN ULANG RESIKO JATUH PADA PASIEN GERIATRI
            </h3>
          </HeaderFormulir>

          <table className='w-full text-xs border-collapse'>
            <thead>
              <tr className='font-bold text-center'>
                <th
                  rowSpan={2}
                  className='border border-black p-2 align-middle'
                >
                  KRITERIA
                </th>
                {tanggalList.map((tgl) => (
                  <th
                    key={tgl}
                    colSpan={grouped[tgl].length}
                    className='border border-black p-2'
                  >
                    {formatDate(tgl)}
                  </th>
                ))}
              </tr>
              <tr className='font-bold text-center'>
                {res.map((d, i) => (
                  <th
                    key={i}
                    className='border border-black p-2 w-[55px] whitespace-nowrap'
                  >
                    {formatDateTimev2(d.insert_dttm)} WIB
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {KRITERIA.map((k, ki) => (
                <tr key={ki}>
                  <td className='border border-black p-2'>{k.label}</td>
                  {res.map((d, di) => (
                    <td
                      key={di}
                      className='border border-black p-2 text-center font-bold'
                    >
                      {d[k.key] == 1 ? '✓' : ''}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
            <tfoot>
              <tr className='font-bold'>
                <td className='border border-black p-2 text-right'>TOTAL</td>
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.total}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td className='border border-black p-2 text-right'>
                  Nama Perawat
                </td>
                {res.map((d, di) => (
                  <td
                    key={di}
                    className='border border-black p-2 text-center text-[10px] break-words'
                  >
                    {d.nama_perawat || ''}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td className='border border-black p-2 text-right'>Paraf</td>
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.nama_perawat ? (
                      <QRCode
                        value={d.nama_perawat}
                        className='w-[45px] h-[45px] mx-auto'
                      />
                    ) : null}
                  </td>
                ))}
              </tr>
            </tfoot>
          </table>

          <p className='text-black mt-3'>
            Skor 1 - 3 = Risiko Rendah | Skor {'>='} 4 = Risiko Tinggi
          </p>
        </div>
      </LayoutBorderNo>
    </div>
  )
}

export default ReportPengkajianUlangResikoJatuhGeriatri
