import { cn } from '@/lib/utils'
import type { AlatUkur } from '@/models/asesmen-geriatri'

type ResikoJatuhTableGeriatriProps = {
  data: AlatUkur
}

const ResikoJatuhTableGeriatri = ({ data }: ResikoJatuhTableGeriatriProps) => {
  return (
    <div className='mb-2'>
      <p className='flex-1 font-semibold'>
        RESIKO JATUH AWAL PADA PASIEN GERIATRI
      </p>
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            KRITERIA
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>Hasil</p>
        </div>
      </div>
      <Item
        k='Gangguan gaya berjalan (diseret, menghentak, berayun)'
        v={data.n1 == 1 ? '✓' : ''}
      />
      <Item k='Pusing, pingsan pada posisi tegak' v={data.n2 == 1 ? '✓' : ''} />
      <Item
        k='Kebingungan setiap saat, misalnya demensia'
        v={data.n3 == 1 ? '✓' : ''}
      />
      <Item k='Nokturia/ Inkontinesia' v={data.n4 == 1 ? '✓' : ''} />
      <Item
        k='Kebingungan intermiten, misalnya delirium/Acute Confusional State'
        v={data.n5 == 1 ? '✓' : ''}
      />
      <Item k='Kelemahan Umum' v={data.n6 == 1 ? '✓' : ''} />
      <Item k='Obat-obatan berisiko tinggi' v={data.n7 == 1 ? '✓' : ''} />
      <Item
        k='Riwayat jatuh dalam 12 bulan terakhir'
        v={data.n8 == 1 ? '✓' : ''}
      />
      <Item k='Osteoporosis' v={data.n9 == 1 ? '✓' : ''} />
      <Item
        k='Gangguan pendengaran dan/atau penglihatan'
        v={data.n10 == 1 ? '✓' : ''}
      />
      <Item k='Usia 70 tahun ke atas' v={data.n11 == 1 ? '✓' : ''} />
      <Item isLast k='Total Skor' v={`${data.total}`} />
      <p className='whitespace-pre-wrap mt-2'>{`TINGKAT RESIKO : \nResiko Rendah Bila Skor : 0-1 \nResiko Sedang Bila Skor : 2-3 \nResiko Tinggi Bila Skor >= 4`}</p>
    </div>
  )
}

export default ResikoJatuhTableGeriatri

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}
