import { PengkajianAwalMppModel } from '@/models/pengkajian-awal-mpp'
import type { Response } from '@/type'

import { post } from './api-2'

const getPengkajianAwalMpp = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<PengkajianAwalMppModel>> => {
  const response = await post(`/v1/pengkajian-mpp`, { no_reg, kd_bagian })
  return response.data
}

export { getPengkajianAwalMpp }
