import { Fragment } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { cn } from '@/lib/utils'
import { ResikoJatuhMorse } from '@/models/resiko-jatuh'
import { getAllResikoJatuhMorse } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTimev2 } from '@/utils/formatDate'

interface ReportPengkajianUlangResikoJatuhDewasaProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

// Skala Morse Falls Scale (MFS) sesuai layout Flutter
type SkalaMorse = {
  title: string
  skor: number
}

type FaktorMorse = {
  title: string
  skala: SkalaMorse[]
}

const contains = (val: string, keys: string[]) =>
  keys.some((k) => val.includes(k))

// Kembalikan judul skala terpilih (persis sama dgn title di buildFaktor)
const faktorSkala = (data: ResikoJatuhMorse, title: string): string => {
  const d = data ?? ({} as ResikoJatuhMorse)
  switch (title) {
    case 'Riwayat Jatuh':
      return contains(d.r_jatuh, ['Ya'])
        ? 'Ya'
        : contains(d.r_jatuh, ['Tidak'])
          ? 'Tidak'
          : ''
    case 'Diagnosis sekunder (>= 2 diagnosis medis)':
      return contains(d.diagnosis, ['Ya'])
        ? 'Ya'
        : contains(d.diagnosis, ['Tidak'])
          ? 'Tidak'
          : ''
    case 'Bantuan Ambulasi':
      return contains(d.ambulasi, ['Furniture', 'dinding', 'meja'])
        ? 'Furniture : dinding, meja, kursi, lemari'
        : contains(d.ambulasi, ['Kruk', 'Tongkat', 'Walker'])
          ? 'Kruk / Tongkat / Walker'
          : contains(d.ambulasi, [
                'tempat tidur',
                'kursi roda',
                'bantuan perawat',
              ])
            ? 'Di tempat tidur / butuh bantuan perawat / memakai kursi roda'
            : ''
    case 'Terpasang infuse':
      return contains(d.terpasang_infuse, ['Ya'])
        ? 'Ya'
        : contains(d.terpasang_infuse, ['Tidak'])
          ? 'Tidak'
          : ''
    case 'Gaya berjalan':
      return contains(d.gaya_berjalan, ['Terganggu'])
        ? 'Terganggu'
        : contains(d.gaya_berjalan, ['Lemah'])
          ? 'Lemah'
          : contains(d.gaya_berjalan, ['Normal', 'tirah baring', 'imobilisasi'])
            ? 'Normal / tirah baring / imobilisasi'
            : ''
    case 'Status mental':
      return contains(d.status_mental, ['Sering lupa'])
        ? 'Sering lupa akan keterbatasan yang dimiliki'
        : contains(d.status_mental, ['Sadar'])
          ? 'Sadar akan kemampuan diri sendiri'
          : ''
    default:
      return ''
  }
}

const buildFaktor = (): FaktorMorse[] => {
  return [
    {
      title: 'Riwayat Jatuh',
      skala: [
        { title: 'Ya', skor: 25 },
        { title: 'Tidak', skor: 0 },
      ],
    },
    {
      title: 'Diagnosis sekunder (>= 2 diagnosis medis)',
      skala: [
        { title: 'Ya', skor: 15 },
        { title: 'Tidak', skor: 0 },
      ],
    },
    {
      title: 'Bantuan Ambulasi',
      skala: [
        {
          title: 'Furniture : dinding, meja, kursi, lemari',
          skor: 30,
        },
        {
          title: 'Kruk / Tongkat / Walker',
          skor: 15,
        },
        {
          title: 'Di tempat tidur / butuh bantuan perawat / memakai kursi roda',
          skor: 0,
        },
      ],
    },
    {
      title: 'Terpasang infuse',
      skala: [
        { title: 'Ya', skor: 20 },
        { title: 'Tidak', skor: 0 },
      ],
    },
    {
      title: 'Gaya berjalan',
      skala: [
        { title: 'Terganggu', skor: 20 },
        { title: 'Lemah', skor: 10 },
        {
          title: 'Normal / tirah baring / imobilisasi',
          skor: 0,
        },
      ],
    },
    {
      title: 'Status mental',
      skala: [
        {
          title: 'Sering lupa akan keterbatasan yang dimiliki',
          skor: 15,
        },
        {
          title: 'Sadar akan kemampuan diri sendiri',
          skor: 0,
        },
      ],
    },
  ]
}

const ReportPengkajianUlangResikoJatuhDewasa = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangResikoJatuhDewasaProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resikoJatuhMorse, noreg],
    queryFn: () =>
      getAllResikoJatuhMorse({ noReg: noreg!, kdBagian: kdBagian! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const faktor = buildFaktor()

  // Grup entri per tanggal -> header tanggal (colSpan) + baris jam
  const grouped = res.reduce<Record<string, ResikoJatuhMorse[]>>((acc, d) => {
    const tgl = (d.insertDttm ?? '').substring(0, 10)
    acc[tgl] = acc[tgl] ?? []
    acc[tgl].push(d)
    return acc
  }, {})
  const tanggalList = Object.keys(grouped).sort()

  return (
    <div className='landscape:max-w-full landscape:m-0'>
      <style>{`
        @media print {
          @page {
            size: A4 landscape;
            margin: 10mm;
          }
          body {
            margin: 0;
            padding: 0;
          }
        }
      `}</style>
      <LayoutBorderNo isReport={isReport} no='RM RI 8d.1' rev='00.2026'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-2'>
              PENGKAJIAN ULANG PASIEN RESIKO JATUH DEWASA
            </h3>
          </HeaderFormulir>

          <p className='text-justify text-black my-2'>
            Lakukan pengkajian (skoring) risiko jatuh pada saat terjadi
            perubahan kondisi pasien/therapi, saat pasien pindah ruangan lain,
            pasien risiko tinggi dikaji setiap 24 jam atau sesaat terjadi kasus
            jatuh.
          </p>

          <table className='w-full text-xs border-collapse'>
            <thead>
              <tr className='font-bold text-center'>
                <th
                  rowSpan={2}
                  className='border border-black p-2 w-[160px] align-middle'
                >
                  Faktor Resiko
                </th>
                <th
                  rowSpan={2}
                  className='border border-black p-2 align-middle'
                >
                  SKALA
                </th>
                <th
                  rowSpan={2}
                  className='border border-black p-2 w-[50px] align-middle'
                >
                  POIN
                </th>
                {tanggalList.map((tgl) => (
                  <th
                    key={tgl}
                    colSpan={grouped[tgl].length}
                    className='border border-black p-2'
                  >
                    {formatDate(tgl)}
                  </th>
                ))}
              </tr>
              <tr className='font-bold text-center'>
                {res.map((d, i) => (
                  <th
                    key={i}
                    className='border border-black p-2 w-[55px] whitespace-nowrap'
                  >
                    {formatDateTimev2(d.insertDttm)} WIB
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {faktor.map((f, fi) => (
                <Fragment key={fi}>
                  {f.skala.map((s, si) => (
                    <tr key={si}>
                      {si === 0 && (
                        <td
                          rowSpan={f.skala.length}
                          className='border border-black p-2 align-middle'
                        >
                          {f.title}
                        </td>
                      )}
                      <td className='border border-black p-2 align-middle'>
                        {s.title}
                      </td>
                      <td className='border border-black p-2 text-center'>
                        {s.skor}
                      </td>
                      {res.map((d, di) => (
                        <td
                          key={di}
                          className={cn(
                            'border border-black p-2 text-center font-bold',
                            faktorSkala(d, f.title) === s.title &&
                              'bg-green-200',
                          )}
                        >
                          {faktorSkala(d, f.title) === s.title ? '✓' : ''}
                        </td>
                      ))}
                    </tr>
                  ))}
                </Fragment>
              ))}
            </tbody>
            <tfoot>
              <tr className='font-bold'>
                <td colSpan={2} className='border border-black p-2 text-right'>
                  TOTAL
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.total}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td colSpan={2} className='border border-black p-2 text-right'>
                  Nama Perawat
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td
                    key={di}
                    className='border border-black p-2 text-center text-[10px] break-words'
                  >
                    {d.nama_perawat || ''}
                  </td>
                ))}
              </tr>
              <tr className='font-bold'>
                <td colSpan={2} className='border border-black p-2 text-right'>
                  Paraf
                </td>
                <td className='border border-black p-2 text-center' />
                {res.map((d, di) => (
                  <td key={di} className='border border-black p-2 text-center'>
                    {d.nama_perawat ? (
                      <QRCode
                        value={d.nama_perawat}
                        className='w-[45px] h-[45px] mx-auto'
                      />
                    ) : null}
                  </td>
                ))}
              </tr>
            </tfoot>
          </table>

          <p className='text-black mt-3 whitespace-pre-wrap'>
            {`Keterangan :
⚫ Tulis jumlah skor yang sesuai pada kolom skor pasien
⚫ Kategori :
   - Resiko rendah  : 0 - 24
   - Resiko sedang : 25 - 44
   - Resiko tinggi    : >= 45`}
          </p>
        </div>
      </LayoutBorderNo>
    </div>
  )
}

export default ReportPengkajianUlangResikoJatuhDewasa
