import { ReactNode } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import Text from '@/components/text'
import { SkriningPasienLuar } from '@/models/skrining-pasien-luar'
import { getSkriningPasienLuarById } from '@/services/skrining-pasien-luar'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportSkriningPasienLuarProps {
  isReport?: boolean
  id?: number
}

const initData: SkriningPasienLuar = {
  insert_dttm: '',
  insert_user_id: '',
  kd_bagian: '',
  id: -1,

  data: {
    petugas: '',
    identitas_pengirim: '',
    hp: '',
    rujukan: '',
    cara_informasi_datang: '',
    diagnosa: '',
    keluhan: '',
    gcs_e: '',
    gcs_m: '',
    gcs_v: '',
    td: '',
    nadi: '',
    suhu: '',
    pernafasan: '',
    spo2: '',
    kebutuhan_sarana: '',
    rekomendasi: '',
    saran: '',
    alamat: '',
    jenis_kelamin: '',
    nama: '',
    nik: '',
    tanggal_lahir: '',
  },
}

const ReportSkriningPasienLuar = ({
  isReport,
  id,
}: ReportSkriningPasienLuarProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.skriningPasienLuar, id],
    queryFn: () => getSkriningPasienLuarById(id!),
    enabled: !!id,
  })

  const res = data?.response ?? initData

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo
      no='RM 7a1'
      rev='RM 7a, Revisi II/IV/2026'
      isReport={isReport}
    >
      {/* Content */}
      <div className='p-2'>
        <HeaderFormulir
          nama={res.data.nama}
          tanggalLahir={res.data.tanggal_lahir}
          nik={res.data.nik}
          jenisKelamin={res.data.jenis_kelamin}
        >
          <h3>
            SKRINING PASIEN DARI LUAR <br />
            RUMAH SAKIT
          </h3>
        </HeaderFormulir>
        <div className='border border-black my-1 p-2'>
          <div className='mb-2'>
            <Text
              k='Nama Petugas Penerima RS St Antonio'
              v={res.data.petugas}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Identitas pengirim dari luar'
              v={res.data.identitas_pengirim}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='No Telepon / HP'
              v={res.data.hp}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Rujukan'
              v={res.data.rujukan}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Cara informasi datang'
              v={res.data.cara_informasi_datang}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Diagnosa'
              v={res.data.diagnosa}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Keluhan Saat Ini'
              v={res.data.keluhan}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <p className='text-xs text-black'>
              Kondisi Saat Ini ( Diisi jika dari sarana kesehatan lain )
            </p>
          </div>
          <div className='mb-2'>
            <Text
              k='Kebutuhan Sarana Yang Diperlukan'
              v={res.data.kebutuhan_sarana}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Rekomendasi'
              v={res.data.rekomendasi}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
          <div className='mb-2'>
            <Text
              k='Saran Selama Transfer (Jika Diterima)'
              v={res.data.saran}
              kStyle='min-w-[250px] font-medium'
            />
          </div>
        </div>

        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <div className='flex items-end justify-between text-xs'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>
                Baturaja, {formatDate(res.insert_dttm)}
              </p>
              {res.data.petugas ? (
                <>
                  <QRCode
                    value={res.data.petugas}
                    className='h-[50px] w-[50px]'
                  />
                  <p>( {res.data.petugas} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportSkriningPasienLuar

interface HeaderFormulirProps {
  nama: string
  tanggalLahir: string
  jenisKelamin: string
  nik: string
  children: ReactNode
}

const HeaderFormulir = ({
  children,
  nama,
  tanggalLahir,
  jenisKelamin,
  nik,
}: HeaderFormulirProps) => {
  return (
    <div className='flex border border-black items-center mb-1'>
      <div className='flex justify-center flex-1 flex-col items-center  border-[0] border-black border-r-[1px] h-[150px] p-2'>
        <div className='text-center font-bold pt-2'>{children}</div>
      </div>
      <div className='flex-1 h-[150px] p-2'>
        <TextField title='Nama' value={nama} />
        <TextField title='Tanggal Lahir' value={formatDate(tanggalLahir)} />
        <TextField title='Jenis Kelamin' value={jenisKelamin} />
        <TextField title='NIK' value={nik} />
      </div>
    </div>
  )
}

export const TextField = ({
  title,
  value,
}: {
  title: string
  value?: string
}) => {
  return (
    <div className='mt-3'>
      <div className='flex items-center'>
        <div className='min-w-[100px]'>
          <p className='text-xs'>{title ?? ''}</p>
        </div>
        <div>
          <p className='text-xs'>: {value ?? ''}</p>
        </div>
      </div>
    </div>
  )
}
