import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import type { DkeluarIcuNakes } from '@/models/masuk-keluar-icu'
import { getKeluarIcuNakes } from '@/services/masuk-keluar-icu'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportKriteriaKeluarIcuNakesProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

const listParameter: { title: string; kriteria: string; key: keyof DkeluarIcuNakes }[] = [
  {
    title: 'Status Kesadaran',
    kriteria: 'GCS > 12 tanpa penurunan kesadaran',
    key: 'p1',
  },
  {
    title: 'Stabilitas Hemodinamik',
    kriteria: 'Tekanan darah stabil tanpa vasopressor',
    key: 'p2',
  },
  {
    title: 'Fungsi Respirasi',
    kriteria: 'Tidak memerlukan ventilator > 24 jam',
    key: 'p3',
  },
  {
    title: 'Intake/Output',
    kriteria: 'Balance cairan stabil selama 24 jam terakhir',
    key: 'p4',
  },
  {
    title: 'Nutrisi',
    kriteria: 'Menerima nutrisi enteral/parenteral dengan baik',
    key: 'p5',
  },
  {
    title: 'Infeksi',
    kriteria: 'Tidak ada tanda infeksi sistemik aktif',
    key: 'p6',
  },
  {
    title: 'Kebutuhan Monitoring',
    kriteria: 'Tidak membutuhkan monitoring invasive kontinu',
    key: 'p7',
  },
  {
    title: 'Rencana Lanjut',
    kriteria: 'Rencana perawatan lanjutan tersedia dan jelas',
    key: 'p8',
  },
]

const ReportKriteriaKeluarIcuNakes = ({
  isReport,
  noreg,
  kdBagian,
}: ReportKriteriaKeluarIcuNakesProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.keluarIcuNakes, noreg],
    queryFn: () => getKeluarIcuNakes(noreg!, kdBagian!),
    enabled: !!noreg,
  })

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const res: DkeluarIcuNakes | null = data != null ? data.response : null

  if (res == null || res.noreg == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const nilaiLabel = (nilai: number) =>
    nilai == 1 ? 'YA' : nilai == 0 ? 'TIDAK' : ''

  return (
    <LayoutBorderNo isReport={isReport} no='RM 11d.5' rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3'>
            KRITERIA PASIEN KELUAR dari ICU
          </h3>
        </HeaderFormulir>

        <div className='border border-black p-1 mb-1'>
          <table className='w-full text-xs'>
            <thead>
              <tr className='border border-black'>
                <th className='border border-black p-1'>Parameter</th>
                <th className='border border-black p-1'>Kriteria Evaluasi</th>
                <th className='border border-black p-1'>Nilai</th>
                <th className='border border-black p-1'>Skor</th>
              </tr>
            </thead>
            <tbody>
              {listParameter.map((item) => (
                <tr key={item.key} className='border border-black align-top'>
                  <td className='border border-black p-1'>{item.title}</td>
                  <td className='border border-black p-1'>{item.kriteria}</td>
                  <td className='border border-black p-1 text-center'>
                    {nilaiLabel(res[item.key] as number)}
                  </td>
                  <td className='border border-black p-1 text-center'>
                    {String(res[item.key])}
                  </td>
                </tr>
              ))}
              <tr className='border border-black align-top'>
                <td className='border border-black p-1 font-bold'>
                  Total Skor
                </td>
                <td className='border border-black p-1' />
                <td className='border border-black p-1' />
                <td className='border border-black p-1 text-center font-bold'>
                  {String(res.total)}
                </td>
              </tr>
            </tbody>
          </table>

          <div className='mt-4'>
            <p className='font-bold'>Interpretasi Total Skor</p>
            <p className='whitespace-pre-line'>
              {`- Skor 7–8: Pasien sangat layak untuk dipindahkan dari ICU.

- Skor 5–6: Pertimbangkan pemindahan dengan pengawasan ketat.

- Skor < 5: Pasien sebaiknya tetap dirawat di ICU.`}
            </p>
          </div>

          {/* Tanda Tangan */}
          <div className='flex items-end justify-between pt-10'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>Perawat</p>
              {res.nama_perawat ? (
                <>
                  <QRCode
                    value={res.nama_perawat}
                    className='h-[50px] w-[50px]'
                  />
                  <p>( {res.nama_perawat} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>
                Baturaja, {formatDate(res.insert_dttm)}
              </p>
              <p className='font-medium'>DPJP</p>
              {res.nama_dokter ? (
                <>
                  <QRCode
                    value={res.nama_dokter}
                    className='h-[50px] w-[50px]'
                  />
                  <p>( {res.nama_dokter} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
          </div>
          {/* Tanda Tangan */}
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default ReportKriteriaKeluarIcuNakes