import type { AsesmenPraBedah } from '@/models/asesmen-pra'
import type { Response } from '@/type'

import { post } from './api-2'

const getAsesmenPraBedah = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<AsesmenPraBedah>> => {
  const response = await post(`/v1/asesmen-pra-bedah`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getAsesmenPraBedah }
