import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { getEarlyWarningSystemPews } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

import { TextTitle } from './text-title'

type KontrolPasienPewsProps = {
  noreg: string
  kdBagian: string
  isReport?: boolean
}

const KontrolPasienPews = ({
  noreg,
  kdBagian,
  isReport,
}: KontrolPasienPewsProps) => {
  const { pasien } = usePasienStore((state) => state)

  const kd = kdBagian || pasien?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.ewsPews, noreg],
    queryFn: () => getEarlyWarningSystemPews(noreg, kd),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const rows = res?.kontrol_pasien.filter((i) => i.kategori == 'ANAK') ?? []
  const keterangan = res?.keterangan

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (rows.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 3a' rev='03.2026'>
      <div className='p-2 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3>PEDIATRIC EARLY WARNING SCORE (PEWS)</h3>
        </HeaderFormulir>

        <TextTitle title='Data Pemantauan PEWS' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Waktu</th>
              <th className='border border-black px-1'>RR</th>
              <th className='border border-black px-1'>SpO2</th>
              <th className='border border-black px-1'>Nadi</th>
              <th className='border border-black px-1'>Suhu</th>
              <th className='border border-black px-1'>TD Sistolik</th>
              <th className='border border-black px-1'>Warna Kulit</th>
              <th className='border border-black px-1'>Perilaku</th>
              <th className='border border-black px-1'>Skor PEWS</th>
              <th className='border border-black px-1'>Ket.</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>
                  {formatDateTime(item.waktu)}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.pernapasan}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.spo2}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.nadi}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.suhu}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.sistolik}
                </td>
                <td className='border border-black px-1'>{item.warna_kulit}</td>
                <td className='border border-black px-1'>{item.perilaku}</td>
                <td className='border border-black px-1 text-center font-semibold'>
                  {item.total}
                </td>
                <td className='border border-black px-1'>
                  {item.keterangan_pews}
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {keterangan != null && (
          <>
            <TextTitle title='Keterangan' />
            <ul className='list-disc list-inside mb-2'>
              {keterangan.ringan != null && (
                <li>Ringan: {keterangan.ringan}</li>
              )}
              {keterangan.sedang != null && (
                <li>Sedang: {keterangan.sedang}</li>
              )}
              {keterangan.tinggi != null && (
                <li>Tinggi: {keterangan.tinggi}</li>
              )}
              {keterangan.sangat_tinggi != null && (
                <li>Sangat Tinggi: {keterangan.sangat_tinggi}</li>
              )}
            </ul>
          </>
        )}
      </div>
    </LayoutBorderNo>
  )
}

export default KontrolPasienPews
