import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getReportAsesmenEdukasiTerintegrasi } from '@/services/edukasi-terintegrasi'
import { usePasienStore } from '@/store/pasien.store'
import { ReportAsesmenEdukasiTerintegrasiModel } from '@/type'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface EdukasiTerintegrasiProps {
  isReport?: boolean
}

const init: ReportAsesmenEdukasiTerintegrasiModel = {
  asesmen: {
    id: 0,
    insert_dttm: '',
    noreg: '',
    kd_bagian: '',
    insert_user_id: '',
    pelayanan: '',
    tinggal_bersama: '',
    hambatan: '',
    edukasi_yang_diberikan: '',
    kemampuan_bahasa: '',
    perlu_penerjemah: '',
    baca_tulis: '',
    kepercayaan: '',
    kesediaan_menerima_edukasi: '',
    cara_edukasi: '',
    kebutuhan_edukasi: '',
  },
  edukasi: [],
}

export function EdukasiTerintegrasi({
  isReport = false,
}: EdukasiTerintegrasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pasien.edukasiTerintegrasi.report],
    queryFn: () => getReportAsesmenEdukasiTerintegrasi(pasien!.no_reg),
  })

  const result = data?.response != null ? data.response : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (result.asesmen.noreg == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo no='RM 2d' rev='03.2020' isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3>
            {' '}
            Formulir Pemberian Informasi, Edukasi dan Evaluasi Ketercapaian
            Edukasi Terintegrasi
          </h3>
        </HeaderFormulir>

        <div className='my-4'>
          <p className='text-black font-medium text-sm'>
            {' '}
            A. PENGKAJIAN KEBUTUHAN EDUKASI
          </p>
          <section className='border border-black p-2 mb-4'>
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Tinggal Bersama'
              v={result.asesmen.tinggal_bersama}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Hambatan'
              v={result.asesmen.hambatan}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Edukasi diberikan kepada'
              v={result.asesmen.edukasi_yang_diberikan}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Kemampuan Bahasa'
              v={result.asesmen.kemampuan_bahasa}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Perlu Penterjemah'
              v={result.asesmen.perlu_penerjemah}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Baca & Tulis'
              v={result.asesmen.baca_tulis}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Kepercayaan Lainnya'
              v={result.asesmen.kepercayaan}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Kesediaan Menerima Edukasi'
              v={result.asesmen.kesediaan_menerima_edukasi}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Cara Edukasi'
              v={result.asesmen.cara_edukasi}
            />
            <Text
              kStyle={`min-w-[200px] mb-1`}
              k='Kebutuhan Edukasi'
              v={result.asesmen.kebutuhan_edukasi}
            />
          </section>

          {/* Header */}
          <p className='text-black font-medium text-sm'> B. EDUKASI</p>
          <div className='flex text-xs'>
            <SimpleColumn
              head
              name='Tgl & Jam Edukasi'
              className='w-[100px] flex-1'
            />
            <SimpleColumn head name='MATERI EDUKASI BERDASARKAN KEBUTUHAN' />
            <SimpleColumn head name='METODE DAN MEDIA' />
            <SimpleColumn head name='LAMA EDUKASI (MENIT)' />
            <SimpleColumn head name='HASIL VERIFIKASI' />
            <SimpleColumn head name='TGL RE-EDUKASI/RE-DEMONSTRASI' />
            <SimpleColumn head name='PEMBERI EDUKASI' />
            <SimpleColumn
              head
              name='PASIEN/ KELUARGA (HUBUNGAN)'
              isLast={isReport}
            />
          </div>
          {/* Header */}

          {/* Body */}

          {result.edukasi.length > 0 &&
            result.edukasi.map((item, index) => (
              <div className='flex text-xs text-wrap' key={index}>
                <SimpleColumn
                  name={formatDateTime(item.insert_dttm)}
                  className='w-[100px] border-t-0 flex-1'
                />
                <SimpleColumn
                  name={item.informasi}
                  className='border-t-0 flex-1'
                />
                <SimpleColumn
                  name={item.metode}
                  className='border-t-0 flex-1'
                />
                <SimpleColumn
                  name={item.lama_edukasi}
                  className='border-t-0 flex-1'
                />
                <SimpleColumn
                  name={item.evaluasi}
                  className='border-t-0 flex-1'
                />
                <SimpleColumn
                  name={
                    item.tanggal_reedukasi != null
                      ? formatDateTime(item.tanggal_reedukasi)
                      : '-'
                  }
                  className='border-t-0 flex-1'
                />
                <SimpleColumn
                  name={item.pemberi_informasi}
                  className='border-t-0 flex-1'
                  hasSignature
                  signatureUrl={item.ttd_pemberi_edukasi}
                />
                <SimpleColumn
                  name={item.penerima_informasi}
                  isLast={isReport}
                  className='border-t-0 flex-1'
                  hasSignature
                  signatureUrl={item.ttd_penerima_edukasi}
                />
              </div>
            ))}
          {/* Body */}
        </div>
      </div>
      {/* Content */}
    </LayoutBorderNo>
  )
}
