import { format } from 'date-fns'
import { id } from 'date-fns/locale'
import { Calendar as CalendarIcon, Download } from 'lucide-react'

import { useEffect, useState } from 'react'

import { useMutation, useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { Calendar } from '@/components/ui/calendar'
import { Input } from '@/components/ui/input'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { DataTable } from '@/features/triase/components/table/data-table'
import { columns } from '@/features/user-log/components/table/columns'
import {
  exportUserLogCsv,
  getUserLog,
  getUserLogBagian,
} from '@/services/user-log'
import { MetaPaginated } from '@/type'
import { constants } from '@/utils/constants'

const LIMIT = 20

export default function UserLog() {
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  // default: hari ini
  const [tanggal, setTanggal] = useState(() => formatYmd(new Date()))
  const [bagian, setBagian] = useState('')
  const [page, setPage] = useState(1)

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search)
      setPage(1)
    }, 400)
    return () => clearTimeout(timer)
  }, [search])

  const { data: listBagian } = useQuery({
    queryKey: [constants.queryKey.userLog.bagian],
    queryFn: getUserLogBagian,
    staleTime: Infinity,
  })

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.userLog.list,
      tanggal,
      bagian,
      debouncedSearch,
      page,
    ],
    queryFn: () =>
      getUserLog({
        tanggal,
        kd_bagian: bagian,
        search: debouncedSearch,
        page,
        limit: LIMIT,
      }),
  })

  const { mutate: onExport, isPending: isExporting } = useMutation({
    mutationFn: () =>
      exportUserLogCsv({
        tanggal,
        kd_bagian: bagian,
        search: debouncedSearch,
      }),
    onSuccess: ({ blob, filename }) => {
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = filename
      a.click()
      URL.revokeObjectURL(url)
    },
  })

  const meta = data?.metadata as MetaPaginated | undefined
  const totalPage = meta?.total_page ?? 1

  if (isLoading) return <Loading />
  if (isError) return <Error className='text-white' />

  return (
    <>
      <div className='flex items-center gap-3 mb-3 flex-wrap'>
        <Input
          placeholder='Cari nama / user id / aktivitas...'
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className='max-w-sm bg-white text-black'
        />
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant='outline'
              className='w-[220px] justify-start bg-white text-black text-left font-normal gap-2'
            >
              <CalendarIcon className='h-4 w-4' />
              {tanggal
                ? format(new Date(tanggal), 'PPP', { locale: id })
                : 'Semua Tanggal'}
            </Button>
          </PopoverTrigger>
          <PopoverContent className='w-auto p-0 bg-white' align='start'>
            <Calendar
              mode='single'
              selected={tanggal ? new Date(tanggal) : undefined}
              onSelect={(d) => {
                setTanggal(d ? formatYmd(d) : '')
                setPage(1)
              }}
            />
          </PopoverContent>
        </Popover>
        <Select
          value={bagian || '__all__'}
          onValueChange={(v) => {
            setBagian(v === '__all__' ? '' : v)
            setPage(1)
          }}
        >
          <SelectTrigger className='w-[200px] bg-white text-black'>
            <SelectValue placeholder='Semua Bagian' />
          </SelectTrigger>
          <SelectContent className='bg-white'>
            <SelectItem value='__all__'>Semua Bagian</SelectItem>
            {listBagian?.response.map((b) => (
              <SelectItem key={b} value={b}>
                {b}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button
          variant='outline'
          className='bg-white text-black gap-2'
          disabled={isExporting}
          onClick={() => onExport()}
        >
          <Download className='h-4 w-4' />
          Export CSV
        </Button>
      </div>

      <DataTable columns={columns} data={data?.response ?? []} />

      <div className='flex items-center justify-between mt-3'>
        <p className='text-white text-sm'>
          Halaman {page} dari {totalPage} ({meta?.total_data ?? 0} data)
        </p>
        <div className='flex gap-2'>
          <Button
            variant='outline'
            size='sm'
            disabled={page <= 1}
            onClick={() => setPage((p) => p - 1)}
            className='text-black'
          >
            &laquo; Sebelumnya
          </Button>
          <Button
            variant='outline'
            size='sm'
            disabled={page >= totalPage}
            onClick={() => setPage((p) => p + 1)}
            className='text-black'
          >
            Selanjutnya &raquo;
          </Button>
        </div>
      </div>
    </>
  )
}

function formatYmd(d: Date) {
  const m = `${d.getMonth() + 1}`.padStart(2, '0')
  const day = `${d.getDate()}`.padStart(2, '0')
  return `${d.getFullYear()}-${m}-${day}`
}
