import { RiwayatPengobatanModel } from '@/models/riwayat-pengobatan-model'
import { Response } from '@/type'

import { post } from './api-2'

const getRekonsiliasiObat = async ({
  no_reg,
}: {
  no_reg: string
}): Promise<Response<RiwayatPengobatanModel[]>> => {
  const response = await post('/v1/rekonsiliasi-obat-report', { no_reg })

  return response.data
}

export { getRekonsiliasiObat }
