import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import type { ReportTransferInternal } from '@/models/transfer-internal'
import { getAllTransferInternal } from '@/services/transfer-internal'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportTransferInternalProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

const ReportTransferInternal = ({
  isReport,
  noreg,
}: ReportTransferInternalProps) => {
  const [index, setIndex] = useState(0)
  const [current, setCurrent] = useState<ReportTransferInternal | null>(null)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.transferInternal, noreg],
    queryFn: () =>
      getAllTransferInternal({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const Default = () => {
    return (
      <LayoutBorderNo isReport={isReport} no='RM 7c' rev='01.2020'>
        <div className='p-4 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-3'>
              TRANSFER PASIEN ANTAR RUANGAN <br />
              (INTERNAL)
            </h3>
          </HeaderFormulir>

          <div className='gap-4 border border-black p-1 mb-1'>
            <div className='mb-4'>
              <TextField title='Dari' value={res[0].data.dari} />
              <TextField title='Pindah ke' value={res[0].data.pindah_ke} />
              <TextField title='DPJP' value={res[0].data.nama_dokter} />
              <TextField
                title='Indikasi Pasien di Rawat Inap'
                value={res[0].data.indikasi_pasien_ranap}
              />
              <TextField
                title='Riwayat Kesehatan Pasien'
                value={res[0].data.riwayat_kesehatan}
              />
            </div>
            <div className='mb-4'>
              <p className='font-semibold'>Pemeriksaan Fisik</p>
              <TextField
                title='1. Keadaan Umum'
                value={res[0].data.keadaan_pasien}
              />
              <TextField title='2. Tanda Vital' />
              <div className='ml-1 flex gap-8'>
                <div>
                  <TextField
                    title='Tekandan Darah'
                    value={`${res[0].pemeriksaan_fisik.td} mmHg`}
                  />

                  <TextField
                    title='Pernafasan'
                    value={`${res[0].pemeriksaan_fisik.pernafasan} x/menit`}
                  />
                  <TextField title='Skor Nyeri' />
                </div>
                <div>
                  <TextField
                    title='Nadi'
                    value={`${res[0].pemeriksaan_fisik.nadi} x/menit`}
                  />

                  <TextField
                    title='Suhu'
                    value={`${res[0].pemeriksaan_fisik.suhu} °C`}
                  />
                  <TextField
                    title='SpO2'
                    value={`${res[0].pemeriksaan_fisik.spo2}%`}
                  />
                </div>
              </div>
              <TextField title='3. Lain-lain' />
            </div>
            <TextField
              title='Pemeriksaan Diagnostik'
              value={res[0].data.pemeriksaan_diagnostik}
            />
            <TextField title='Diagnosa' value={res[0].data.diagnosa} />
            <TextField
              title='Prosedur tindakan yang telah dilakukan'
              value={res[0].data.prosedur}
            />
            <TextField
              title='Obat yang telah diberikan'
              value={res[0].data.obat}
            />
            <TextField
              title='Rencana Lanjutan'
              value={res[0].data.rencana_lanjutan}
            />
            <TextField
              title='Keadaan pasien waktu dipindahkan'
              value={res[0].data.keadaan_pasien}
            />
            <TextField title='Kesadaran' value={res[0].data.kesadaran} />
            <TextField title='GCS' value={res[0].data.gcs} />
            <TextField title='Mobilisasi' value={res[0].data.mobilisasi} />
            <TextField
              title='Transportasi'
              value={res[0].data.transportasi_transfer}
            />
            <TextField title='Diet' value={res[0].data.diet} />
            {/* Tanda Tangan */}
            <div className='ml-4'>
              <div className='py-10' />
              <div className='flex items-end justify-between'>
                <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
                  <p className='font-medium'>Petugas Penerima</p>
                  {res[0].data.nama_penerima ? (
                    <>
                      <QRCode
                        value={res[0].data.nama_penerima}
                        className='h-[50px] w-[50px]'
                      />
                      <p>( {res[0].data.nama_penerima} )</p>
                    </>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                </div>
                <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
                  <p className='font-medium'>
                    Baturaja, {formatDateTime(res[0].data.insert_dttm)}
                  </p>
                  <p className='font-medium'>Petugas Menyerahkan</p>
                  {res[0].data.nama_pemberi ? (
                    <>
                      <QRCode
                        value={res[0].data.nama_pemberi}
                        className='h-[50px] w-[50px]'
                      />
                      <p>( {res[0].data.nama_pemberi} )</p>
                    </>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                </div>
              </div>
            </div>
            {/* Tanda Tangan */}
          </div>
        </div>
      </LayoutBorderNo>
    )
  }

  const Current = () => {
    return (
      <LayoutBorderNo isReport={isReport} no='RM 7c' rev='01.2020'>
        <div className='p-4 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-3'>
              TRANSFER PASIEN ANTAR RUANGAN <br />
              (INTERNAL)
            </h3>
          </HeaderFormulir>

          <div className='gap-4 border border-black p-1 mb-1'>
            <div className='mb-4'>
              <TextField title='Dari' value={current?.data?.dari} />
              <TextField title='Pindah ke' value={current?.data?.pindah_ke} />
              <TextField title='DPJP' value={current?.data?.nama_dokter} />
              <TextField
                title='Indikasi Pasien di Rawat Inap'
                value={current?.data?.indikasi_pasien_ranap}
              />
              <TextField
                title='Riwayat Kesehatan Pasien'
                value={current?.data?.riwayat_kesehatan}
              />
            </div>
            <div className='mb-4'>
              <p className='font-semibold'>Pemeriksaan Fisik</p>
              <TextField
                title='1. Keadaan Umum'
                value={current?.data?.keadaan_pasien}
              />
              <TextField title='2. Tanda Vital' />
              <div className='ml-1 flex gap-8'>
                <div>
                  <TextField
                    title='Tekandan Darah'
                    value={`${current?.pemeriksaan_fisik?.td} mmHg`}
                  />

                  <TextField
                    title='Pernafasan'
                    value={`${current?.pemeriksaan_fisik?.pernafasan} x/menit`}
                  />
                  <TextField title='Skor Nyeri' />
                </div>
                <div>
                  <TextField
                    title='Nadi'
                    value={`${current?.pemeriksaan_fisik?.nadi} x/menit`}
                  />

                  <TextField
                    title='Suhu'
                    value={`${current?.pemeriksaan_fisik?.suhu} °C`}
                  />
                  <TextField
                    title='SpO2'
                    value={`${current?.pemeriksaan_fisik?.spo2}%`}
                  />
                </div>
              </div>
              <TextField title='3. Lain-lain' />
            </div>
            <TextField
              title='Pemeriksaan Diagnostik'
              value={current?.data?.pemeriksaan_diagnostik}
            />
            <TextField title='Diagnosa' value={current?.data?.diagnosa} />
            <TextField
              title='Prosedur tindakan yang telah dilakukan'
              value={current?.data?.prosedur}
            />
            <TextField
              title='Obat yang telah diberikan'
              value={current?.data?.obat}
            />
            <TextField
              title='Rencana Lanjutan'
              value={current?.data?.rencana_lanjutan}
            />
            <TextField
              title='Keadaan pasien waktu dipindahkan'
              value={current?.data?.keadaan_pasien}
            />
            <TextField title='Kesadaran' value={current?.data?.kesadaran} />
            <TextField title='GCS' value={current?.data?.gcs} />
            <TextField title='Mobilisasi' value={current?.data?.mobilisasi} />
            <TextField
              title='Transportasi'
              value={current?.data?.transportasi_transfer}
            />
            <TextField title='Diet' value={current?.data?.diet} />
            {/* Tanda Tangan */}
            <div className='ml-4'>
              <div className='py-10' />
              <div className='flex items-end justify-between'>
                <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
                  <p className='font-medium'>Petugas Penerima</p>
                  {current?.data?.nama_penerima ? (
                    <>
                      <QRCode
                        value={current?.data?.nama_penerima}
                        className='h-[50px] w-[50px]'
                      />
                      <p>( {current?.data?.nama_penerima} )</p>
                    </>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                </div>
                <div className='w-full text-center flex flex-col justify-between items-center gap-2'>
                  <p className='font-medium'>
                    Baturaja, {formatDate(current?.data?.insert_dttm ?? '')}
                  </p>
                  <p className='font-medium'>Petugas Menyerahkan</p>
                  {current?.data?.nama_pemberi ? (
                    <>
                      <QRCode
                        value={current?.data?.nama_pemberi}
                        className='h-[50px] w-[50px]'
                      />
                      <p>( {current?.data?.nama_pemberi} )</p>
                    </>
                  ) : (
                    <div className='h-[50px]' />
                  )}
                </div>
              </div>
            </div>
            {/* Tanda Tangan */}
          </div>
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {res != null &&
        res.length > 0 &&
        res.map((item, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setCurrent(item)
              setIndex(idx)
            }}
          >
            {idx + 1}
          </Button>
        ))}

      {current == null ? <Default /> : <Current />}
    </>
  )
}

export default ReportTransferInternal
