import type {
  DkeluarIcuNakes,
  DmasukKeluarIcu,
} from '@/models/masuk-keluar-icu'
import type { Response } from '@/type'

import { post } from './api-2'

const getMasukKeluarIcu = async (
  no_reg: string,
  kd_bagian: string,
  kategori: string,
): Promise<Response<DmasukKeluarIcu>> => {
  const response = await post(`/v1/masuk-keluar-icu`, {
    no_reg,
    kd_bagian,
    kategori,
  })

  return response.data
}

const getKeluarIcuNakes = async (
  no_reg: string,
  kd_bagian: string,
): Promise<Response<DkeluarIcuNakes>> => {
  const response = await post(`/v1/keluar-icu-nakes`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getKeluarIcuNakes, getMasukKeluarIcu }