import { ImplementasiMppModel } from '@/models/implementasi-mpp'
import type { Response } from '@/type'

import { post } from './api-2'

const getImplementasiMpp = async ({
  no_reg,
  kd_bagian,
  no_rm,
}: {
  no_reg: string
  kd_bagian: string
  no_rm: string
}): Promise<Response<ImplementasiMppModel>> => {
  const response = await post(`/v1/implementasi-mpp/report`, {
    no_reg,
    kd_bagian,
    no_rm,
  })

  return response.data
}

export { getImplementasiMpp }
