import type { DuserLog } from '@/models/user-log'
import type { Response } from '@/type'

import { get } from './api-2'

const getUserLog = async ({
  tanggal,
  kd_bagian,
  search,
  page,
  limit,
}: {
  tanggal?: string
  kd_bagian?: string
  search?: string
  page?: number
  limit?: number
}): Promise<Response<DuserLog[]>> => {
  const response = await get('/v1/user-log', {
    tanggal,
    kd_bagian,
    search,
    page,
    limit,
  })

  return response.data
}

const exportUserLogCsv = async ({
  tanggal,
  kd_bagian,
  search,
}: {
  tanggal?: string
  kd_bagian?: string
  search?: string
}): Promise<{ blob: Blob; filename: string }> => {
  const response = await get('/v1/user-log', {
    tanggal,
    kd_bagian,
    search,
    export: 'csv',
  })

  return {
    // axios mengembalikan string mentah utk text/csv
    blob: new Blob([response.data as string], {
      type: 'text/csv;charset=utf-8',
    }),
    filename: `user-log-${tanggal || 'semua'}-${kd_bagian || 'semua'}.csv`,
  }
}

const getUserLogBagian = async (): Promise<Response<string[]>> => {
  const response = await get('/v1/user-log-bagian')

  return response.data
}

export { exportUserLogCsv, getUserLog, getUserLogBagian }
