import { cn } from '@/lib/utils'
import type { DischargePlanning } from '@/models/asesmen-geriatri'

type DischargePlanningProps = {
  data: DischargePlanning
}

const DischargePlanning = ({ data }: DischargePlanningProps) => {
  return (
    <div className='mb-2'>
      {/* <p className='flex-1 font-semibold'>Discharge Planning</p> */}
      <div className='flex'>
        <div className='flex-1 border border-black border-r-0 border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>
            KRITERIA
          </p>
        </div>
        <div className='flex-[0.5] border border-black border-b-0 p-2'>
          <p className='text-black text-xs text-center font-semibold'>HASIL</p>
        </div>
      </div>
      <Item k='Umur > 65 Tahun' v={data.n1} />
      <Item k='Keterbatasan mobilitas' v={data.n2} />
      <Item k='Percobaan bunuh diri' v={data.n3} />
      <Item k='Korban dan kasus kriminal' v={data.n4} />
      <Item k='Perawatan atau pengobatan jaringan' v={data.n5} />
      <Item
        isLast
        k='Bantuan untuk melakukan aktifitas sehari-hari'
        v={data.n6}
      />
    </div>
  )
}

export default DischargePlanning

const Item = ({ k, v, isLast }: { k: string; v: string; isLast?: boolean }) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex-1 border border-black border-r-0  p-2 border-b-[0] ',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{k}</p>
      </div>
      <div
        className={cn(
          'flex-[0.5] border border-black p-2 border-b-[0]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p className='text-black text-xs'>{v}</p>
      </div>
    </div>
  )
}
