import { AsesmenAwalKebidanan } from '@/models/asesmen-awal-kebidanan'
import { Response } from '@/type'

import { post } from './api-2'

const getAsesmenAwalKebidanan = async ({
  noreg,
  noRm,
}: {
  noreg: string
  noRm: string
}): Promise<Response<AsesmenAwalKebidanan>> => {
  const response = await post(`/v1/report-pengkajian-kebidanan`, {
    no_reg: noreg,
    no_rm: noRm,
  })

  return response.data
}

export { getAsesmenAwalKebidanan }
